28	const SCHEMA = {
29	  type: 'object',
30	  properties: {
31	    description: { type: 'string' },
32	    quote: { type: 'string' },
33	    source_url: { type: 'string' },
34	  },
35	  required: ['description', 'quote', 'source_url'],
36	};
37	
38	interface Extraction {
39	  description: string;
40	  quote: string;
41	  source_url: string;
42	}
