44	const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
45	
46	function quoteAppears(quote: string, text: string): boolean {
47	  const q = norm(quote);
48	  if (q.length < 15) return false;
49	  const c = norm(text);
50	  if (c.includes(q)) return true;
51	  const head = q.split(' ').slice(0, 6).join(' ');
52	  return head.length >= 15 && c.includes(head);
53	}
54	
55	/** A LinkedIn company URL, not a post, job ad, or people-directory page. */
56	function companyLinkedin(url: string): string | null {
57	  const m = url.match(/^https?:\/\/[a-z]{0,3}\.?linkedin\.com\/company\/[a-zA-Z0-9._-]+/);
58	  return m ? m[0].replace(/^http:/, 'https:') : null;
59	}
60	
61	/** A LinkedIn member profile URL. */
62	function personLinkedin(url: string): string | null {
63	  const m = url.match(/^https?:\/\/[a-z]{0,3}\.?linkedin\.com\/in\/[a-zA-Z0-9._%-]+/);
64	  return m ? m[0].replace(/^http:/, 'https:') : null;
65	}
66	
67	/**
68	 * A person's profile only counts when the search that found it named both the
69	 * person and their firm. Matching on surname alone attaches the wrong Smith.
70	 */
71	function nameMatches(url: string, title: string, snippet: string, personName: string): boolean {
72	  const parts = personName
73	    .replace(/,/g, ' ')
74	    .toLowerCase()
75	    .replace(/\b(mr|mrs|ms|miss|dr|sir|dame|lord|lady|prof)\b/g, ' ')
76	    .split(/\s+/)
77	    .filter((t) => t.length >= 3);
78	  if (parts.length < 2) return false;
79	
80	  const haystack = `${url} ${title} ${snippet}`.toLowerCase();
81	  const hits = parts.filter((p) => haystack.includes(p)).length;
82	  return hits >= 2;
83	}
