STOP = set("the a an and or of in on at to for with is are was were be been has have had it its this that these those their they which as by from also more than who".split())
def content_words(s):
    return [w for w in re.sub(r'[^a-z0-9\s.]',' ',s.lower()).split() if len(w)>2 and w not in STOP]
def hard_tokens(s):
    return [t.lower().rstrip('.,') for t in re.findall(r'\b\d[\d,./-]*\b|\b[A-Z][a-zA-Z&.\'-]{2,}\b', s)]

def lexical_support(value, evidence_text):
    """The same two tests attribution.ts applies to generated claims."""
    hay = evidence_text.lower()
    missing_hard = [t for t in hard_tokens(str(value)) if t not in hay]
    if missing_hard:
        return False, f"not in evidence: {', '.join(missing_hard[:3])}"
    words = content_words(str(value))
    if not words:
        return True, ""
    cov = sum(1 for w in words if w in hay)/len(words)
    return (cov >= 0.6, "" if cov >= 0.6 else f"only {round(cov*100)}% of terms appear")

# walk every populated cell that carries evidence
