const checks: Check[] = [];

async function attempt(name: string, expect: 'accept' | 'reject', run: () => Promise<unknown>) {
  let got: string;
  try {
    await run();
    got = 'accepted';
  } catch (err) {
    got = err instanceof Error ? err.message.split('\n')[0] : String(err);
  }
