            VALUES (${P + '-obs-a'}, ${P + '-src'}, 'https://example.test/a', 'hash-a'),
                   (${P + '-obs-b'}, ${P + '-src'}, 'https://example.test/b', 'hash-b')`;
  await sql`INSERT INTO s2_entity (id, canonical_name) VALUES (${P + '-ent'}, 'PTC-10 Test Ltd')`;
  await sql`INSERT INTO s2_extraction_event (id, observation_id, extractor)
            VALUES (${P + '-ev-a'}, ${P + '-obs-a'}, 'verify'),
