  claimId: string,
  eventId: string,
  role: EvidenceRole,
  input: EvidenceInput,
): Evidence {
  return {
    id: `ev_${randomUUID()}`,
    claimId,
    observationId: input.observationId,
    extractionEventId: eventId,
    role,
    spanText: input.spanText,
    spanStart: input.spanStart,
