attachment.snippet:
1	/**
2	 * Adversarial check on the M1 contract.
3	 *
4	 * The Stage 1 defect was a value shipped wearing evidence from a different fact.
5	 * M1 claims that is now unexpressible. A claim like that is worth nothing until
6	 * the database has actually refused the write, so this attempts the mis-wiring
7	 * directly and fails loudly if Postgres lets it through.
8	 *
9	 * Run: npx tsx packages/db/src/verify-ptc10.ts
10	 */
11	import 'dotenv/config';
12	import { neon } from '@neondatabase/serverless';
13	
14	const sql = neon(process.env.DATABASE_URL!);
15	const P = 'ptc10test';
16	
17	type Check = { name: string; expect: 'accept' | 'reject'; got: string; pass: boolean };
18	const checks: Check[] = [];
19	
20	async function attempt(name: string, expect: 'accept' | 'reject', run: () => Promise<unknown>) {
21	  let got: string;
22	  try {
23	    await run();
24	    got = 'accepted';
25	  } catch (err) {
26	    got = err instanceof Error ? (err.message.split('\n')[0] ?? err.message) : String(err);
27	  }
28	  const accepted = got === 'accepted';
29	  checks.push({ name, expect, got, pass: accepted === (expect === 'accept') });
30	}
31	
32	async function cleanup() {
33	  // children first; evidence cascades from claim but events/observations do not
34	  await sql`DELETE FROM s2_evidence WHERE id LIKE ${P + '%'}`;
35	  await sql`DELETE FROM s2_claim WHERE id LIKE ${P + '%'}`;
36	  await sql`DELETE FROM s2_extraction_event WHERE id LIKE ${P + '%'}`;
37	  await sql`DELETE FROM s2_observation WHERE id LIKE ${P + '%'}`;
38	  await sql`DELETE FROM s2_entity WHERE id LIKE ${P + '%'}`;
39	  await sql`DELETE FROM s2_source WHERE id LIKE ${P + '%'}`;
40	}
41	
42	async function main() {
43	  await cleanup();
44	
45	  // Two observations of two different documents, read in two separate events.
46	  // Event A established the claim. Event B is the "other fact" whose evidence
47	  // Stage 1 would have copied across.
48	  await sql`INSERT INTO s2_source (id, kind, identifier, tier)
49	            VALUES (${P + '-src'}, 'companies_house', ${P}, 1)`;
50	  await sql`INSERT INTO s2_observation (id, source_id, url, content_hash)
51	            VALUES (${P + '-obs-a'}, ${P + '-src'}, 'https://example.test/a', 'hash-a'),
52	                   (${P + '-obs-b'}, ${P + '-src'}, 'https://example.test/b', 'hash-b')`;
53	  await sql`INSERT INTO s2_entity (id, canonical_name) VALUES (${P + '-ent'}, 'PTC-10 Test Ltd')`;
54	  await sql`INSERT INTO s2_extraction_event (id, observation_id, extractor)
55	            VALUES (${P + '-ev-a'}, ${P + '-obs-a'}, 'verify'),
56	                   (${P + '-ev-b'}, ${P + '-obs-b'}, 'verify')`;
57	  await sql`INSERT INTO s2_claim (id, entity_id, extraction_event_id, field, value_json, value_type)
58	            VALUES (${P + '-claim'}, ${P + '-ent'}, ${P + '-ev-a'},
59	                    'registered_address', ${JSON.stringify('1 Test Street')}::jsonb, 'address')`;
60	
61	  // 1. THE STAGE 1 DEFECT ITSELF. Establishing evidence for a claim made in
62	  //    event A, carrying event B's reading. This is build-dataset.ts:144.
63	  await attempt('establishing evidence from a foreign extraction event', 'reject', () =>
64	    sql`INSERT INTO s2_evidence (id, claim_id, observation_id, extraction_event_id, role, span_text, method)
65	        VALUES (${P + '-e1'}, ${P + '-claim'}, ${P + '-obs-b'}, ${P + '-ev-b'},
66	                'establishing', 'unrelated quote from document B', 'copied at assembly time')`,
67	  );
68	
69	  // 2. The correct write must still be easy.
70	  await attempt('establishing evidence from the claim\'s own event', 'accept', () =>
71	    sql`INSERT INTO s2_evidence (id, claim_id, observation_id, extraction_event_id, role, span_text, method)
72	        VALUES (${P + '-e2'}, ${P + '-claim'}, ${P + '-obs-a'}, ${P + '-ev-a'},
73	                'establishing', 'Registered office: 1 Test Street', 'read from the filing')`,
74	  );
75	
76	  // 3. One establishing row per claim, so a second cannot quietly replace the first.
77	  await attempt('a second establishing row on the same claim', 'reject', () =>
78	    sql`INSERT INTO s2_evidence (id, claim_id, observation_id, extraction_event_id, role, span_text, method)
79	        VALUES (${P + '-e3'}, ${P + '-claim'}, ${P + '-obs-a'}, ${P + '-ev-a'},
80	                'establishing', 'duplicate', 'read from the filing')`,
81	  );
82	
83	  // 4. Corroboration from a later, different event must remain free — a second
84	  //    source agreeing next week is the normal case, not a violation.
85	  await attempt('corroborating evidence from a different event', 'accept', () =>
86	    sql`INSERT INTO s2_evidence (id, claim_id, observation_id, extraction_event_id, role, span_text, method)
87	        VALUES (${P + '-e4'}, ${P + '-claim'}, ${P + '-obs-b'}, ${P + '-ev-b'},
88	                'corroborating', 'Address given as 1 Test Street', 'independent confirmation')`,
89	  );
90	
91	  // 5. So must conflicting evidence — recording disagreement is the point.
92	  await attempt('conflicting evidence from a different event', 'accept', () =>
93	    sql`INSERT INTO s2_evidence (id, claim_id, observation_id, extraction_event_id, role, span_text, method)
94	        VALUES (${P + '-e5'}, ${P + '-claim'}, ${P + '-obs-b'}, ${P + '-ev-b'},
95	                'conflicting', 'Address given as 2 Other Road', 'independent source disagrees')`,
96	  );
97	
98	  // 6. A claim cannot be released with no basis at all. Not a DB constraint --
99	  //    the release gate owns this -- so it is asserted here as a query, to be
100	  //    explicit that the schema alone does not cover it.
101	  const orphans = await sql`
102	    SELECT c.id FROM s2_claim c
103	    WHERE NOT EXISTS (SELECT 1 FROM s2_evidence e WHERE e.claim_id = c.id AND e.role = 'establishing')`;
104	  checks.push({
105	    name: 'no claim lacks establishing evidence (gate-enforced, not schema-enforced)',
106	    expect: 'accept',
107	    got: orphans.length === 0 ? 'accepted' : `${orphans.length} orphan claim(s)`,
108	    pass: orphans.length === 0,
109	  });
110	
111	  await cleanup();
112	
113	  let failed = 0;
114	  for (const c of checks) {
115	    if (!c.pass) failed++;
116	    const mark = c.pass ? 'ok  ' : 'FAIL';
117	    const detail = c.got === 'accepted' ? 'accepted' : `rejected: ${c.got.slice(0, 78)}`;
118	    console.log(`  ${mark}  [expect ${c.expect}] ${c.name}\n          ${detail}`);
119	  }
120	  console.log(failed === 0 ? '\nPTC-10 holds at the database level.' : `\n${failed} check(s) failed.`);
121	  process.exit(failed === 0 ? 0 : 1);
122	}
123	
124	main().catch(async (err) => {
125	  await cleanup().catch(() => {});
126	  console.error(err);
127	  process.exit(1);
128	});

