cd "/Users/atq/Drive E/fo-intel" && node -e '
const d = JSON.parse(require("fs").readFileSync("data/fo-dataset.json","utf8"));
const rows = Array.isArray(d) ? d : (d.records || d.firms || Object.values(d)[0]);
console.log("count:", rows.length);
console.log("keys:", Object.keys(rows[0]).join(", "));
' 2>&1 | head -20

cd "/Users/atq/Drive E/fo-intel" && node -e '
const rows = JSON.parse(require("fs").readFileSync("data/fo-dataset.json","utf8"));
const kopp = rows.find(r=>/kopp/i.test(r.legalName));
const duq  = rows.find(r=>/duquesne/i.test(r.legalName));
const emer = rows.find(r=>/emerson/i.test(r.legalName));
for (const [nm,r] of [["KOPP",kopp],["DUQUESNE",duq],["EMERSON",emer]]) {
  if(!r){console.log(nm,"not found");continue;}
  console.log("=====",nm,r.legalName);
  console.log(JSON.stringify({street:r.street,postcode:r.postcode,city:r.city,country:r.country}));
  console.log("principals:", JSON.stringify(r.principals,null,1).slice(0,1400));
}
' 2>&1 | head -80

