  await db.sql`INSERT INTO s2_decision_log (id, run_id, entity_id, kind, rule, after_json, reason)
               VALUES (${'dl_' + RUN}, ${RUN}, ${ENTITY}, 'classify', 'commercial_floor',
                       ${JSON.stringify(commercial)}::jsonb, ${commercial.reason})`;
