6	/**
7	 * SEC 13F signature blocks — the reachability channel.
8	 *
9	 * Companies House gives breadth and statutory control evidence and zero contact
10	 * routes. This is the only measured channel that produces a phone number filed
11	 * beside a named individual in a document that individual signed.
12	 *
13	 * The Phase 0 census found 9,874 unique firm+person routes, of which 6,940
14	 * adjudicate to an individual. My stated prior before measuring was that these
15	 * would mostly be switchboards and fail ownership; that was wrong, and the
16	 * adjudication below is why. Exclusions are deterministic and principled:
17	 *
18	 *   - a number filed by more than one filer is an administrator line (one number
19	 *     covered 18 JPMorgan entities)
20	 *   - a signatory that is not a natural person is not a person
21	 *   - a number shared by two signatories at the same filer belongs to neither
22	 *
23	 * What this channel cannot do is reach beyond US 13F filers. A UK company or a
24	 * Gulf family office cannot appear in this census at all, which is assumption A5
25	 * and the reason the file's composition is a trade rather than a free choice.
26	 */
27	
28	const SEC_DIR = 'data/sec';
29	
30	export const SEC_13F_SOURCE: Source = {
31	  id: 'src_sec_13f',
32	  kind: 'sec_13f',
33	  identifier: 'sec.gov/form-13f/2025q3',
34	  baseUrl: 'https://www.sec.gov',
