40	interface SigRow { ACCESSION_NUMBER: string; NAME: string; TITLE: string; PHONE: string }
41	interface CoverRow { ACCESSION_NUMBER: string; FILINGMANAGER_NAME: string; DATEREPORTED: string }
42	
43	function tsv<T>(path: string): T[] {
44	  const lines = readFileSync(path, 'utf8').split('\n').filter(Boolean);
45	  const head = lines[0]!.split('\t').map((h) => h.trim());
46	  return lines.slice(1).map((l) => {
47	    const cells = l.split('\t');
48	    const o: Record<string, string> = {};
49	    head.forEach((h, i) => { o[h] = (cells[i] ?? '').trim(); });
50	    return o as T;
51	  });
52	}
53	
54	const digits = (s: string) => (s ?? '').replace(/\D/g, '');
55	
56	const NOT_A_PERSON =
57	  /\b(department|compliance|committee|group|llc|inc|corp|ltd|limited|lp|trust|company|partners|management|administrator|services|team|office)\b/i;
58	
59	export function isNaturalPerson(name: string): boolean {
60	  const n = name.trim();
61	  if (n.length < 4) return false;
62	  if (NOT_A_PERSON.test(n)) return false;
63	  return n.replace(/[^A-Za-z ,.'-]/g, '').split(/[\s,]+/).filter((t) => t.length > 1).length >= 2;
64	}
65	
66	export interface SignatoryRoute {
67	  firm: string; accession: string; person: string; title: string;
68	  phone: string; filedOn: string;
69	  ownership: 'individual' | 'company' | 'unknown';
70	  reason: string;
71	  cik?: string;
72	}
73	
74	/** Normalised for joining a filer name to a candidate's legal name. */
75	export function normFirm(s: string): string {
76	  return s.toUpperCase()
77	    .replace(/[.,]/g, ' ')
78	    .replace(/\b(L\s?L\s?C|L\s?P|LLP|INC|CORP|CORPORATION|COMPANY|CO|LTD|LIMITED|TRUST|THE)\b/g, ' ')
79	    .replace(/[^A-Z0-9 ]/g, ' ')
80	    .replace(/\s+/g, ' ')
