11	/**
12	 * The loop every job shares: collect, extract, gate, release, checkpoint.
13	 *
14	 * Written once because the interesting property is uniformity -- every claim
15	 * from every source passes the same gates and the same chokepoint. A source that
16	 * needed its own release path would be a source whose data nobody had checked.
17	 */
18	
19	const db = contractWriter(process.env.DATABASE_URL!);
20	
21	export interface ProcessOptions {
22	  run: RunHandle;
23	  source: Source;
24	  collector: Collector;
25	  extractor: Extractor;
26	  /** stable, deterministic id so re-running upserts rather than duplicates */
27	  entityFor: (observation: Observation) => { id: string; canonicalName: string; entityType?: string };
28	  /** stop after this many units; the budget guard, in its simplest form */
29	  maxUnits?: number;
30	  resume?: boolean;
31	}
32	
33	export async function processSource(opts: ProcessOptions): Promise<void> {
34	  const { run, source, collector, extractor, entityFor } = opts;
35	  const maxUnits = opts.maxUnits ?? Number(process.env.MAX_UNITS ?? 40);
36	
37	  await db.upsertSource(source);
38	  const cursor = opts.resume === false ? undefined : (await run.readCheckpoint(source.id)) ?? undefined;
39	  await run.log('info', 'source_started', { source: source.id, resumeFrom: cursor ?? null, maxUnits });
40	
41	  let units = 0;
42	
43	  for await (const { observation, cursor: next } of collector.collect(source, cursor)) {
44	    if (units >= maxUnits) {
45	      await run.log('info', 'budget_halt', { source: source.id, units, reason: 'maxUnits reached' });
46	      await run.decision('budget_halt', {
47	        rule: 'max_units_per_run',
48	        reason: `stopped after ${units} units to stay inside the run budget`,
49	        after: { cursor: next },
50	      });
51	      break;
52	    }
53	
54	    try {
55	      await processObservation(observation, { run, source, extractor, entityFor });
56	      units++;
57	      run.counts.touched++;
58	
59	      // Checkpoint AFTER the writes have committed. See migration 004.
60	      if (next) await run.checkpoint(source.id, next, units);
61	    } catch (err) {
62	      const message = err instanceof Error ? err.message : String(err);
63	      run.failures.push({ source: source.id, url: observation.url, message });
64	      await run.log('error', 'unit_failed', { url: observation.url, message });
65	      // One bad unit must not end the run -- an unattended system that stops on
66	      // the first malformed record is a system that stops.
67	    }
68	  }
69	
70	  await run.log('info', 'source_finished', { source: source.id, units });
71	}
72	
73	async function processObservation(
74	  observation: Observation,
75	  ctx: Pick<ProcessOptions, 'run' | 'source' | 'extractor' | 'entityFor'>,
76	): Promise<void> {
77	  const { run, extractor, entityFor } = ctx;
78	  const ent = entityFor(observation);
79	
80	  // Evidence-based staleness: if we have seen this exact content before, there
81	  // is nothing new to extract. A clock alone never justifies re-extraction.
82	  const seen = (await db.sql`
83	    SELECT id FROM s2_observation WHERE url = ${observation.url} AND content_hash = ${observation.contentHash}
84	    LIMIT 1`) as unknown as Array<{ id: string }>;
85	  if (seen.length) {
86	    await run.log('debug', 'unchanged', { url: observation.url, hash: observation.contentHash });
87	    return;
88	  }
89	
90	  const priorRows = (await db.sql`
91	    SELECT content_hash FROM s2_observation WHERE url = ${observation.url}
92	    ORDER BY fetched_at DESC LIMIT 1`) as unknown as Array<{ content_hash: string }>;
93	  const prior = priorRows[0]?.content_hash;
94	
95	  await db.upsertObservation(observation);
96	
97	  const entity: Entity = {
98	    id: ent.id, canonicalName: ent.canonicalName, entityType: ent.entityType ?? 'unconfirmed',
99	    firstSeenAt: new Date(), trustState: 'active', commercialState: 'unassessed',
100	    strictReachable: false, profileAssistedReachable: false,
101	  };
102	  await db.upsertEntity(entity);
103	
104	  if (prior) {
105	    // A content change with a recorded before/after is the staleness evidence
106	    // the brief asks for. Recorded when it happens, not reconstructed later.
107	    await run.decision('stale', {
108	      entityId: ent.id, rule: 'content_hash_changed',
109	      before: { contentHash: prior }, after: { contentHash: observation.contentHash },
110	      reason: `source content at ${observation.url} changed, so its claims are re-derived`,
111	    });
112	    await run.log('info', 'content_changed', { url: observation.url, from: prior, to: observation.contentHash });
113	  }
114	
115	  const event = openExtractionEvent({ observation, extractor: extractor.name, runId: run.id });
116	  await extractor.extract(observation, event);
