1	import { createHash, randomUUID } from 'node:crypto';
2	import { readFileSync } from 'node:fs';
3	import type { Collector, Extractor, Observation, Source } from '@fo/core/contract/index.js';
4	import type { OpenExtractionEvent } from '@fo/core/contract/index.js';
5	
6	/**
7	 * SEC 13F signature blocks — the reachability channel.
8	 *
9	 * Companies House gives breadth and statutory control evidence and zero contact
10	 * routes. This is the only measured channel that produces a phone number filed
11	 * beside a named individual in a document that individual signed.
12	 *
13	 * The Phase 0 census found 9,874 unique firm+person routes, of which 6,940
14	 * adjudicate to an individual. My stated prior before measuring was that these
15	 * would mostly be switchboards and fail ownership; that was wrong, and the
16	 * adjudication below is why. Exclusions are deterministic and principled:
17	 *
18	 *   - a number filed by more than one filer is an administrator line (one number
19	 *     covered 18 JPMorgan entities)
20	 *   - a signatory that is not a natural person is not a person
21	 *   - a number shared by two signatories at the same filer belongs to neither
22	 *
23	 * What this channel cannot do is reach beyond US 13F filers. A UK company or a
24	 * Gulf family office cannot appear in this census at all, which is assumption A5
25	 * and the reason the file's composition is a trade rather than a free choice.
26	 */
27	
28	const SEC_DIR = 'data/sec';
29	
30	export const SEC_13F_SOURCE: Source = {
31	  id: 'src_sec_13f',
32	  kind: 'sec_13f',
33	  identifier: 'sec.gov/form-13f/2025q3',
34	  baseUrl: 'https://www.sec.gov',
35	  tier: 1,
36	  rateLimitPerMin: 600,
37	  consecutiveFailures: 0,
38	};
39	
40	interface SigRow { ACCESSION_NUMBER: string; NAME: string; TITLE: string; PHONE: string }
41	interface CoverRow {
42	  ACCESSION_NUMBER: string; FILINGMANAGER_NAME: string; DATEREPORTED: string;
43	  FILINGMANAGER_STREET1: string; FILINGMANAGER_CITY: string;
44	  FILINGMANAGER_STATEORCOUNTRY: string; FILINGMANAGER_ZIPCODE: string;
45	}
46	
47	function tsv<T>(path: string): T[] {
48	  const lines = readFileSync(path, 'utf8').split('\n').filter(Boolean);
49	  const head = lines[0]!.split('\t').map((h) => h.trim());
50	  return lines.slice(1).map((l) => {
51	    const cells = l.split('\t');
52	    const o: Record<string, string> = {};
53	    head.forEach((h, i) => { o[h] = (cells[i] ?? '').trim(); });
54	    return o as T;
55	  });
56	}
57	
58	const digits = (s: string) => (s ?? '').replace(/\D/g, '');
59	
60	const NOT_A_PERSON =
61	  /\b(department|compliance|committee|group|llc|inc|corp|ltd|limited|lp|trust|company|partners|management|administrator|services|team|office)\b/i;
62	
63	export function isNaturalPerson(name: string): boolean {
64	  const n = name.trim();
65	  if (n.length < 4) return false;
66	  if (NOT_A_PERSON.test(n)) return false;
67	  return n.replace(/[^A-Za-z ,.'-]/g, '').split(/[\s,]+/).filter((t) => t.length > 1).length >= 2;
68	}
69	
70	export interface SignatoryRoute {
71	  firm: string; accession: string; person: string; title: string;
72	  phone: string; filedOn: string;
73	  ownership: 'individual' | 'company' | 'unknown';
74	  reason: string;
75	  cik?: string;
76	}
77	
78	/**
79	 * The filer's own address, as filed on the cover page.
80	 *
81	 * Already present in COVERPAGE.tsv beside the manager name -- no new source and
82	 * no extra fetch. It matters because a route to a person is only commercially
83	 * usable alongside enough context to act on, and without it a reachable record
84	 * fails the commercial floor and counts toward nothing.
85	 */
86	export interface FilerAddress {
87	  street: string; city: string; stateOrCountry: string; zip: string;
88	}
89	
90	/** Normalised for joining a filer name to a candidate's legal name. */
91	export function normFirm(s: string): string {
92	  return s.toUpperCase()
93	    .replace(/[.,]/g, ' ')
94	    .replace(/\b(L\s?L\s?C|L\s?P|LLP|INC|CORP|CORPORATION|COMPANY|CO|LTD|LIMITED|TRUST|THE)\b/g, ' ')
95	    .replace(/[^A-Z0-9 ]/g, ' ')
96	    .replace(/\s+/g, ' ')
97	    .trim();
98	}
99	
100	/** Populated as a side effect of the census pass; keyed by accession. */
101	const addressByAccession = new Map<string, FilerAddress>();
102	
103	export function addressFor(accession: string): FilerAddress | undefined {
104	  return addressByAccession.get(accession);
105	}
