107	export function buildSignatoryRoutes(dir = SEC_DIR): SignatoryRoute[] {
108	  const sigs = tsv<SigRow>(`${dir}/SIGNATURE.tsv`);
109	  const covers = new Map(tsv<CoverRow>(`${dir}/COVERPAGE.tsv`).map((c) => [c.ACCESSION_NUMBER, c]));
110	
111	  // pass 1 — how widely is each number used across the whole census?
112	  const phoneToFirms = new Map<string, Set<string>>();
113	  const phoneToPeople = new Map<string, Set<string>>();
114	  for (const s of sigs) {
