1	/**
2	 * Derivation rules — the registry behind the third evidence kind.
3	 *
4	 * Gate 2 knows two kinds of evidence: quoting ("the value is written here") and
5	 * pointer ("the value is in the record this names"). Neither fits a value that
6	 * is *computed* from what the source says. A filing gives `MN`; the record needs
7	 * `United States`. That string appears nowhere in the document, so quoting
8	 * evidence fails it, and Phase 1 duly quarantined it.
9	 *
10	 * Quarantining was the correct behaviour for the rules as written and the wrong
11	 * outcome for the data. The fix is not to exempt derived values from checking --
12	 * that would reintroduce exactly the "unchecked value looks checked" failure the
13	 * contract exists to prevent. It is to make the derivation itself checkable:
14	 *
15	 *   the span holds the INPUT, `method` names a rule in this registry, and the
16	 *   gate passes only if the input is present in the span AND re-running the rule
17	 *   reproduces the value.
18	 *
19	 * So a derived value is re-derived at validation time, by a different code path
20	 * than the one that produced it. A rule that is not registered cannot be cited,
21	 * and a value that the rule does not reproduce fails.
22	 *
23	 * Rules must be pure, total and deterministic. No network, no model, no clock.
24	 */
25	
26	export const DERIVED_PREFIX = 'derived:';
27	
28	export type DerivationRule = {
29	  id: string;
30	  /** what the rule reads, for the human-readable method sentence */
31	  describes: string;
32	  apply: (input: string) => string | null;
33	};
34	
35	const US_STATES: Record<string, string> = {
36	  AL: 'Alabama', AK: 'Alaska', AZ: 'Arizona', AR: 'Arkansas', CA: 'California',
37	  CO: 'Colorado', CT: 'Connecticut', DE: 'Delaware', DC: 'District of Columbia',
38	  FL: 'Florida', GA: 'Georgia', HI: 'Hawaii', ID: 'Idaho', IL: 'Illinois',
39	  IN: 'Indiana', IA: 'Iowa', KS: 'Kansas', KY: 'Kentucky', LA: 'Louisiana',
40	  ME: 'Maine', MD: 'Maryland', MA: 'Massachusetts', MI: 'Michigan', MN: 'Minnesota',
41	  MS: 'Mississippi', MO: 'Missouri', MT: 'Montana', NE: 'Nebraska', NV: 'Nevada',
42	  NH: 'New Hampshire', NJ: 'New Jersey', NM: 'New Mexico', NY: 'New York',
43	  NC: 'North Carolina', ND: 'North Dakota', OH: 'Ohio', OK: 'Oklahoma', OR: 'Oregon',
44	  PA: 'Pennsylvania', RI: 'Rhode Island', SC: 'South Carolina', SD: 'South Dakota',
45	  TN: 'Tennessee', TX: 'Texas', UT: 'Utah', VT: 'Vermont', VA: 'Virginia',
46	  WA: 'Washington', WV: 'West Virginia', WI: 'Wisconsin', WY: 'Wyoming',
47	};
48	
49	/**
50	 * The same table the rules use, exported so producers can ask "does this rule
51	 * apply?" before making a claim. Two separate lists would drift.
52	 */
53	export const US_STATE_CODES = new Set(Object.keys(US_STATES));
54	
55	/** UK home nations are countries in the register's sense and one country in ISO's. */
56	const UK_NATIONS = new Set(['england', 'wales', 'scotland', 'northern ireland', 'great britain', 'united kingdom', 'gb', 'uk']);
57	
58	const RULES: DerivationRule[] = [
59	  {
60	    id: 'us_state_to_country',
61	    describes: 'a two-letter US state code',
62	    apply: (input) => (US_STATES[input.trim().toUpperCase()] ? 'United States' : null),
63	  },
64	  {
65	    id: 'us_state_code_to_name',
66	    describes: 'a two-letter US state code',
67	    apply: (input) => US_STATES[input.trim().toUpperCase()] ?? null,
68	  },
69	  {
70	    id: 'uk_nation_to_country',
71	    describes: 'a UK home nation',
72	    apply: (input) => (UK_NATIONS.has(input.trim().toLowerCase()) ? 'United Kingdom' : null),
73	  },
74	];
75	
76	const REGISTRY = new Map(RULES.map((r) => [r.id, r]));
77	
78	export function getRule(id: string): DerivationRule | undefined {
79	  return REGISTRY.get(id);
80	}
81	
82	/** `method` looks like `derived:us_state_to_country from "MN"` */
83	export function parseDerivedMethod(method: string): { ruleId: string; input: string } | null {
84	  if (!method.startsWith(DERIVED_PREFIX)) return null;
85	  const rest = method.slice(DERIVED_PREFIX.length);
86	  const m = /^([a-z0-9_]+)\s+from\s+"(.+)"$/i.exec(rest.trim());
87	  if (!m) return null;
88	  return { ruleId: m[1]!, input: m[2]! };
89	}
90	
91	export function derivedMethod(ruleId: string, input: string): string {
92	  return `${DERIVED_PREFIX}${ruleId} from "${input}"`;
93	}
94	
95	/**
96	 * Re-derive and compare. This is the whole check.
97	 */
98	export function checkDerivation(
99	  value: unknown,
100	  spanText: string,
101	  method: string,
102	): { outcome: 'passed' | 'failed'; detail: string; counterfactual?: unknown } | null {
103	  const parsed = parseDerivedMethod(method);
104	  if (!parsed) return null;
105	
106	  const rule = getRule(parsed.ruleId);
107	  if (!rule) {
108	    // An unregistered rule is an unauditable one. Refusing it is the point:
109	    // otherwise `method` becomes free text that can claim anything.
110	    return {
111	      outcome: 'failed',
112	      detail: `derivation rule "${parsed.ruleId}" is not registered`,
113	      counterfactual: { wouldHaveReleased: value, citingUnknownRule: parsed.ruleId },
114	    };
115	  }
116	
117	  // The input must actually appear in the source we read. Without this the rule
118	  // could be fed a value invented at extraction time.
119	  const inputPresent = new RegExp(`(^|[^A-Za-z0-9])${parsed.input.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}([^A-Za-z0-9]|$)`, 'i')
120	    .test(spanText);
121	  if (!inputPresent) {
122	    return {
123	      outcome: 'failed',
124	      detail: `derivation input "${parsed.input}" does not appear in the span`,
125	      counterfactual: { wouldHaveReleased: value, derivedFromAbsentInput: parsed.input },
126	    };
127	  }
128	
129	  const recomputed = rule.apply(parsed.input);
130	  if (recomputed === null) {
131	    return {
132	      outcome: 'failed',
133	      detail: `rule ${rule.id} does not apply to "${parsed.input}"`,
134	      counterfactual: { wouldHaveReleased: value, ruleReturned: null },
135	    };
136	  }
137	  if (String(value).trim().toLowerCase() !== recomputed.trim().toLowerCase()) {
138	    return {
139	      outcome: 'failed',
140	      detail: `rule ${rule.id} on "${parsed.input}" yields "${recomputed}", not "${String(value)}"`,
141	      counterfactual: { wouldHaveReleased: value, ruleActuallyYields: recomputed },
142	    };
143	  }
144	
145	  return {
146	    outcome: 'passed',
147	    detail: `re-derived "${recomputed}" from ${rule.describes} "${parsed.input}" present in the span`,
148	  };
149	}

