51	
52	const PLAN_PROMPT = (question: string) => `You are planning how to answer a question about a family-office dataset.
53	
54	You may ONLY use these tools. They read released, gate-passed claims:
55	${TOOL_SCHEMAS.map((t) => `- ${t.name}: ${t.description}\n  input: ${JSON.stringify(t.input_schema.properties)}`).join('\n')}
56	
57	Question: "${question}"
58	
59	First, break the question into its explicit constraints. For EACH, say whether the
60	tools can honour it exactly.
61	
62	Mark honourable=false when the dataset cannot express the constraint. Examples of
63	constraints that are NOT honourable: filtering by assets under management, by
64	investment sector or mandate, by number of employees, by founding family surname,
65	by anything requiring semantic similarity rather than a name substring.
66	
67	Being honest that a constraint cannot be honoured is CORRECT and expected. Do not
68	claim you can honour something to look capable.
69	
70	Then list up to ${MAX_CALLS} tool calls.
71	
72	Return JSON:
73	{"constraints":[{"constraint":"...","honourable":true,"why":"..."}],
74	 "calls":[{"tool":"search_firms","input":{...},"because":"..."}]}`;
75	
76	const COMPOSE_PROMPT = (question: string, results: string, unhonoured: string[]) => `Answer the question using ONLY the tool results below.
77	
78	Question: "${question}"
79	
80	Tool results:
81	${results}
82	
83	${unhonoured.length ? `You could NOT honour these constraints:
84	${unhonoured.map((c) => `- ${c}`).join('\n')}
85	
86	You MUST state this plainly in your answer, in the first two sentences, in plain
87	words. Say which part of the question you could not do and what you did instead.
88	An answer that quietly ignores these is worse than no answer.` : 'All constraints were honourable.'}
89	
90	Rules:
91	- Every firm you name must appear in the tool results. Never name one that does not.
92	- Never upgrade a label: a company inbox is not a principal's email; "not found" is not "does not exist".
93	- State the scope: how many were searched, how many MATCHED. Use the `matched`
94	  number from the tool scope, never the length of the returned data array — the
95	  array is a truncated page, and reporting its length understates the answer.
96	- If a firm is missing a field, say it is missing. Do not estimate it.
97	- Be concise and specific. No preamble.
98	
99	Return JSON: {"answer":"..."}`;
100	
101	export async function runAgent(question: string): Promise<AgentAnswer> {
102	  const trace: AgentTrace[] = [];
103	  const now = () => new Date().toISOString();
104	  const push = (kind: AgentTrace['kind'], detail: unknown) =>
105	    trace.push({ step: trace.length + 1, kind, detail, at: now() });
106	
107	  // ---- plan --------------------------------------------------------------
108	  const plan = await generateJson<Plan>(PLAN_PROMPT(question), {
109	    type: 'object',
110	    properties: {
111	      constraints: { type: 'array', items: { type: 'object' } },
112	      calls: { type: 'array', items: { type: 'object' } },
113	    },
114	  });
115	  push('plan', plan);
116	
117	  const unhonoured = (plan.constraints ?? [])
118	    .filter((c) => !c.honourable)
119	    .map((c) => `${c.constraint} — ${c.why}`);
120	
121	  // ---- act ---------------------------------------------------------------
122	  const toolsUsed: string[] = [];
123	  const scope: Record<string, unknown>[] = [];
124	  const collected: string[] = [];
125	
126	  for (const call of (plan.calls ?? []).slice(0, MAX_CALLS)) {
127	    const fn = TOOLS[call.tool];
128	    if (!fn) {
129	      push('tool', { tool: call.tool, error: 'no such tool' });
130	      continue;
131	    }
132	    try {
133	      const r: ToolResult<unknown> = await fn(call.input ?? {});
134	      toolsUsed.push(call.tool);
135	      scope.push({ tool: call.tool, ...r.scope });
136	      push('tool', { tool: call.tool, input: call.input, scope: r.scope, excluded: r.excluded, rows: Array.isArray(r.data) ? r.data.length : 1 });
137	      collected.push(
