152	    push('compose', { answer, reason: 'no tool results' });
153	    return { answer, unhonouredConstraints: unhonoured, blocked: false, toolsUsed, scope, trace };
154	  }
155	
156	  // ---- compose -----------------------------------------------------------
157	  const composed = await generateJson<{ answer: string }>(
