178	      push('block', { blockReason, unhonoured });
179	      answer =
180	        `I could not fully answer this as asked. ` +
181	        `${unhonoured.map((u) => u.split(' — ')[0]).join('; ')} — the dataset does not hold that, so I did not filter on it.\n\n` +

