73	export interface NameResolution {
74	  text: string;
75	  /** names silently corrected to their stored spelling */
76	  corrected: Array<{ wrote: string; stored: string }>;
77	  /** firm-like names with no counterpart in the tool output at all */
78	  fabricated: string[];
79	  /** [[entityId]] tokens the tools never returned */
