126	    let best: { name: string; d: number } | null = null;
127	    for (const [n, name] of byNorm) {
128	      const d = editDistance(norm, n);
129	      if (!best || d < best.d) best = { name, d };
130	    }
131	    if (best && best.d <= Math.max(2, Math.floor(norm.length * 0.12))) {
132	      corrected.push({ wrote: phrase, stored: best.name });
133	      return best.name;
134	    }
135	
136	    fabricated.push(phrase);
137	    return null;
138	  };
139	
140	  // 2. backstop: any firm-like prose the model wrote by hand. A matched span may
141	  // hold several firms in a comma-separated list, so it is segmented first.
142	  text = text.replace(CANDIDATE, (match) => {
143	    if (!COMPANYISH.test(match)) return match;
144	    const segments = match.split(LIST_BREAK);
145	    if (segments.length === 1) {
