115	export function resolveCounts(answer: string, reg: MetricRegistry): CountResolution {
116	  const resolved: Array<{ token: string; value: number }> = [];
117	  const unresolvedTokens: string[] = [];
118	  const unsupported: number[] = [];
119	
120	  const text = answer.replace(TOKEN, (_m, key: string) => {
121	    const v = reg.values.get(key);
122	    if (v === undefined) {
123	      unresolvedTokens.push(key);
124	      return '(a count no tool produced)';
125	    }
126	    resolved.push({ token: key, value: v });
127	    return String(v);
128	  });
129	
130	  // Backstop. A number in count-shaped prose must be one the tools produced.
131	  for (const m of text.matchAll(COUNT_CONTEXT)) {
132	    const raw = m[1] ?? m[2] ?? m[3];
133	    if (raw === undefined) continue;
134	    const n = Number(raw);
135	    if (!Number.isFinite(n)) continue;
136	    if (reg.known.has(n)) continue;
137	    if (!unsupported.includes(n)) unsupported.push(n);
138	  }
139	
140	  return { text, resolved, unresolvedTokens, unsupported };
141	}

