input.command:
cd "/Users/atq/Drive E/fo-intel" && cat > packages/db/src/__live.ts <<'TS'
import 'dotenv/config';
import { connect } from './connect.js';
const sql = connect();
const [e] = await sql`SELECT count(*)::int total,
  count(*) FILTER (WHERE commercial_state='qualifying')::int qualifying,
  count(*) FILTER (WHERE strict_reachable)::int strict,
  count(*) FILTER (WHERE profile_assisted_reachable)::int assisted,
  count(*) FILTER (WHERE commercial_state='qualifying' AND strict_reachable)::int both
  FROM s2_entity` as any[];
const [c] = await sql`SELECT count(*) FILTER (WHERE status='released')::int released,
  count(*) FILTER (WHERE status='quarantined')::int quarantined,
  count(*) FILTER (WHERE status='candidate')::int held FROM s2_claim` as any[];
const runs = await sql`SELECT id, job, trigger, status, started_at, ended_at, records_touched
  FROM s2_run ORDER BY started_at DESC LIMIT 6` as any[];
const cp = await sql`SELECT job, source_id, cursor, units_done, updated_at, last_run_id FROM s2_checkpoint ORDER BY updated_at DESC` as any[];
console.log('ENTITIES:', JSON.stringify(e));
console.log('CLAIMS  :', JSON.stringify(c));
console.log('RECENT RUNS:'); for (const r of runs) console.log(' ', JSON.stringify(r));
console.log('CHECKPOINTS:'); for (const r of cp) console.log(' ', JSON.stringify(r));
TS
npx tsx packages/db/src/__live.ts 2>&1 | grep -v dotenvx; rm -f packages/db/src/__live.ts

