38	export function recordMetrics(
39	  reg: MetricRegistry,
40	  tool: string,
41	  callIndex: number,
42	  scope: Record<string, unknown>,
43	  excluded: Array<{ reason: string; count: number }>,
44	  data: unknown,
45	): void {
46	  const put = (field: string, value: unknown) => {
47	    if (typeof value !== 'number' || !Number.isFinite(value)) return;
48	    const bare = `${tool}.${field}`;
49	    if (!reg.values.has(bare)) reg.values.set(bare, value);
50	    reg.values.set(`${tool}#${callIndex}.${field}`, value);
51	    reg.known.add(value);
52	  };
53	
54	  for (const field of ['searched', 'matched', 'returned', 'releasedClaims', 'rows']) {
55	    put(field, scope[field]);
56	  }
57	  if (data && typeof data === 'object' && !Array.isArray(data)) {
58	    put('count', (data as Record<string, unknown>).count);
59	  }
60	  if (Array.isArray(data)) put('dataLength', data.length);
61	
62	  // Only register an exclusion total when there were exclusions. A tool with
63	  // none would otherwise register 0 as a legitimate figure and whitelist the
64	  // exact number the composer invented ("0 firms matched").
65	  if (excluded.length) {
66	    let excludedTotal = 0;
67	    for (const e of excluded) {
68	      excludedTotal += e.count;
69	      reg.known.add(e.count);
70	    }
71	    put('excludedTotal', excludedTotal);
72	  }
73	}
