2	 * Firm names are not generative.
3	 *
4	 * In production the agent wrote "BARRINGTON COMPANIES MANAGEMENT, LLC" when the
5	 * dataset holds "BARINGTON" — one letter, invented on the way out of the
6	 * composer while the tool data underneath was correct. For a product whose whole
7	 * claim is that every value traces to evidence, a firm name the model typed from
8	 * memory is a fabricated value, however small the edit.
9	 *
10	 * So the composer never writes firm names at all. It writes `[[entityId]]`
11	 * tokens, and the server substitutes the stored `legalName`. A name that does
12	 * not exist in the tool output cannot be produced, because the model is not the
13	 * thing producing names.
14	 *
15	 * The scan afterwards is the backstop for a model that ignores the instruction:
16	 * anything that still looks like a firm name is matched against the canonical
17	 * set, near-misses are corrected to the stored spelling, and anything with no
18	 * match at all blocks the answer.
19	 */
20	
21	/** Tokens that make a capitalised phrase look like a company rather than prose. */
22	const COMPANYISH =
23	  /\b(LLC|L\.L\.C\.?|LTD|LIMITED|INC|INCORPORATED|CORP|CORPORATION|COMPANY|CO|PLC|GMBH|LP|L\.P\.?|LLP|PARTNERS|HOLDINGS?|CAPITAL|MANAGEMENT|INVESTMENTS?|VENTURES?|GROUP|TRUST|OFFICE)\b/i;
24	
25	/** A run of capitalised / all-caps words, i.e. a plausible firm mention. */
26	const CANDIDATE = /\b([A-Z][A-Za-z&'’.-]*(?:[ ,]+(?:[A-Z][A-Za-z&'’.-]*|of|and|the|for)){0,7}(?:,?\s*(?:LLC|L\.L\.C\.?|LTD|LIMITED|INC\.?|CORP\.?|L\.P\.?|LP|LLP|PLC))?)/g;
27	
28	/**
29	 * A legal suffix ends a firm name, so the comma after it separates list items
30	 * rather than continuing one name.
31	 *
32	 * Without this the matcher swallows "Timonier Family Office, LTD., Virtus Family
33	 * Office LLC" as a single phrase, finds no firm by that name, and blocks an
34	 * answer in which every firm was real. Over-blocking a correct answer is worse
35	 * than the misspelling this guard exists to catch.
36	 */
37	const LIST_BREAK = /(?<=\b(?:LLC|L\.L\.C\.?|LTD\.?|LIMITED|INC\.?|CORP\.?|L\.P\.?|LP|LLP|PLC))\s*[,;]\s+(?=[A-Z])/g;
