39	/** Trailing punctuation is sentence grammar, not part of the stored name. */
40	function trimEdges(s: string): string {
41	  return s.replace(/^[\s,;.]+/, '').replace(/[\s,;]+$/, '').replace(/\.$/, '');
42	}
