44	export function normaliseName(s: string): string {
45	  return s
46	    .toUpperCase()
47	    .replace(/[.,'’&-]/g, ' ')
48	    .replace(/\b(L\s*L\s*C|L\s*P|LLP|INC|CORP|CORPORATION|COMPANY|CO|LTD|LIMITED|PLC|THE)\b/g, ' ')
49	    .replace(/[^A-Z0-9 ]/g, ' ')
50	    .replace(/\s+/g, ' ')
