96	    const key = String(id).trim();
97	    const name = canonical.get(key);
98	    if (name) return name;
99	    unresolvedTokens.push(key);
100	    return '(a firm the tools did not return)';
101	  });
102	
103	  if (canonical.size === 0) return { text, corrected, fabricated, unresolvedTokens };
104	
105	  const byNorm = new Map<string, string>();
106	  for (const name of canonical.values()) byNorm.set(normaliseName(name), name);
107	  const exact = new Set(canonical.values());
108	
109	  // 2. Account for every stored name that actually appears, before judging
110	  //    anything. Segmenting prose into firm mentions with a regex proved
111	  //    unreliable in both directions -- it swallowed comma-separated lists of
112	  //    real firms as one phantom name, and its suffix list was case-sensitive.
113	  //
114	  //    Inverting is sturdier: mark the spans that ARE stored names, then only
115	  //    scrutinise what is left over. A real name can never be flagged, because
116	  //    it is matched before the scan runs.
117	  const consumed: Array<[number, number]> = [];
118	  const claim = (from: number, len: number) => consumed.push([from, from + len]);
119	  const overlaps = (from: number, to: number) =>
120	    consumed.some(([a, b]) => from < b && to > a);
121	
122	  for (const stored of [...exact].sort((a, b) => b.length - a.length)) {
123	    const needle = stored.toLowerCase();
124	    let at = text.toLowerCase().indexOf(needle);
125	    while (at !== -1) {
126	      if (!overlaps(at, at + stored.length)) claim(at, stored.length);
127	      at = text.toLowerCase().indexOf(needle, at + 1);
128	    }
129	  }
130	
131	  // 3. Whatever firm-like prose remains was written by the model, not taken
132	  //    from the data. Correct a near miss to the stored spelling; flag anything
133	  //    with no counterpart at all.
134	  //    Claimed spans are masked character-for-character rather than skipped.
135	  //    Skipping a candidate that merely *touches* a known name would let a
136	  //    fabricated firm hide behind a real one in the same sentence — the
137	  //    greedy match spans both, overlaps, and gets waved through. Masking keeps
