54	/** Cheap edit distance, capped — only used to decide "did they mean this one?" */
55	function editDistance(a: string, b: string): number {
56	  if (Math.abs(a.length - b.length) > 4) return 99;
57	  const prev = Array.from({ length: b.length + 1 }, (_, i) => i);
58	  const cur = new Array<number>(b.length + 1);
59	  for (let i = 1; i <= a.length; i++) {
60	    cur[0] = i;
61	    for (let j = 1; j <= b.length; j++) {
62	      cur[j] = Math.min(
63	        prev[j]! + 1,
64	        cur[j - 1]! + 1,
65	        prev[j - 1]! + (a[i - 1] === b[j - 1] ? 0 : 1),
66	      );
67	    }
68	    for (let j = 0; j <= b.length; j++) prev[j] = cur[j]!;
69	  }
70	  return prev[b.length]!;
71	}
