6	
7	/**
8	 * SEC 13F signature blocks — the reachability channel.
9	 *
10	 * Companies House gives breadth and statutory control evidence and zero contact
11	 * routes. This is the only measured channel that produces a phone number filed
12	 * beside a named individual in a document that individual signed.
13	 *
14	 * The Phase 0 census found 9,874 unique firm+person routes, of which 6,940
15	 * adjudicate to an individual. My stated prior before measuring was that these
16	 * would mostly be switchboards and fail ownership; that was wrong, and the
17	 * adjudication below is why. Exclusions are deterministic and principled:
18	 *
19	 *   - a number filed by more than one filer is an administrator line (one number
20	 *     covered 18 JPMorgan entities)
21	 *   - a signatory that is not a natural person is not a person
22	 *   - a number shared by two signatories at the same filer belongs to neither
23	 *
24	 * What this channel cannot do is reach beyond US 13F filers. A UK company or a
25	 * Gulf family office cannot appear in this census at all, which is assumption A5
26	 * and the reason the file's composition is a trade rather than a free choice.
27	 */
28	
29	const SEC_DIR = 'data/sec';
30	
31	export const SEC_13F_SOURCE: Source = {
32	  id: 'src_sec_13f',
33	  kind: 'sec_13f',
34	  identifier: 'sec.gov/form-13f/2025q3',
35	  baseUrl: 'https://www.sec.gov',
36	  tier: 1,
37	  rateLimitPerMin: 600,
38	  consecutiveFailures: 0,
39	};
40	
41	interface SigRow { ACCESSION_NUMBER: string; NAME: string; TITLE: string; PHONE: string }
42	interface CoverRow {
43	  ACCESSION_NUMBER: string; FILINGMANAGER_NAME: string; DATEREPORTED: string;
44	  FILINGMANAGER_STREET1: string; FILINGMANAGER_CITY: string;
45	  FILINGMANAGER_STATEORCOUNTRY: string; FILINGMANAGER_ZIPCODE: string;
46	}
47	
48	function tsv<T>(path: string): T[] {
49	  const lines = readFileSync(path, 'utf8').split('\n').filter(Boolean);
50	  const head = lines[0]!.split('\t').map((h) => h.trim());
51	  return lines.slice(1).map((l) => {
52	    const cells = l.split('\t');
53	    const o: Record<string, string> = {};
54	    head.forEach((h, i) => { o[h] = (cells[i] ?? '').trim(); });
55	    return o as T;
56	  });
57	}
58	
59	const digits = (s: string) => (s ?? '').replace(/\D/g, '');
60	
61	const NOT_A_PERSON =
62	  /\b(department|compliance|committee|group|llc|inc|corp|ltd|limited|lp|trust|company|partners|management|administrator|services|team|office)\b/i;
63	
64	export function isNaturalPerson(name: string): boolean {
65	  const n = name.trim();
66	  if (n.length < 4) return false;
67	  if (NOT_A_PERSON.test(n)) return false;
68	  return n.replace(/[^A-Za-z ,.'-]/g, '').split(/[\s,]+/).filter((t) => t.length > 1).length >= 2;
69	}
70	
71	export interface SignatoryRoute {
72	  firm: string; accession: string; person: string; title: string;
73	  phone: string; filedOn: string;
74	  ownership: 'individual' | 'company' | 'unknown';
75	  reason: string;
76	  cik?: string;
77	}
78	
79	/**
80	 * The filer's own address, as filed on the cover page.
81	 *
82	 * Already present in COVERPAGE.tsv beside the manager name -- no new source and
83	 * no extra fetch. It matters because a route to a person is only commercially
84	 * usable alongside enough context to act on, and without it a reachable record
85	 * fails the commercial floor and counts toward nothing.
86	 */
87	export interface FilerAddress {
88	  street: string; city: string; stateOrCountry: string; zip: string;
89	}
90	
91	/** Normalised for joining a filer name to a candidate's legal name. */
92	export function normFirm(s: string): string {
93	  return s.toUpperCase()
94	    .replace(/[.,]/g, ' ')
95	    .replace(/\b(L\s?L\s?C|L\s?P|LLP|INC|CORP|CORPORATION|COMPANY|CO|LTD|LIMITED|TRUST|THE)\b/g, ' ')
96	    .replace(/[^A-Z0-9 ]/g, ' ')
97	    .replace(/\s+/g, ' ')
98	    .trim();
99	}
100	
101	/** Populated as a side effect of the census pass; keyed by accession. */
102	const addressByAccession = new Map<string, FilerAddress>();
103	
104	export function addressFor(accession: string): FilerAddress | undefined {
105	  return addressByAccession.get(accession);
106	}
107	
108	export function buildSignatoryRoutes(dir = SEC_DIR): SignatoryRoute[] {
109	  const sigs = tsv<SigRow>(`${dir}/SIGNATURE.tsv`);
110	  const covers = new Map(tsv<CoverRow>(`${dir}/COVERPAGE.tsv`).map((c) => [c.ACCESSION_NUMBER, c]));
111	
112	  // pass 1 — how widely is each number used across the whole census?
113	  const phoneToFirms = new Map<string, Set<string>>();
114	  const phoneToPeople = new Map<string, Set<string>>();
115	  for (const s of sigs) {
116	    const c = covers.get(s.ACCESSION_NUMBER);
117	    const p = digits(s.PHONE);
118	    if (!c || !p || !s.NAME) continue;
119	    const firm = c.FILINGMANAGER_NAME.trim();
120	    if (!phoneToFirms.has(p)) phoneToFirms.set(p, new Set());
121	    if (!phoneToPeople.has(p)) phoneToPeople.set(p, new Set());
122	    phoneToFirms.get(p)!.add(firm);
123	    // normalise so "Jeff Sarrett" and "Jeffrey Sarrett" are not counted as two
124	    phoneToPeople.get(p)!.add(s.NAME.toLowerCase().replace(/[^a-z]/g, '').slice(0, 12));
125	  }
126	
127	  const seen = new Set<string>();
128	  const out: SignatoryRoute[] = [];
129	  for (const s of sigs) {
130	    const c = covers.get(s.ACCESSION_NUMBER);
131	    const p = digits(s.PHONE);
132	    if (!c || !p || !s.NAME) continue;
133	    const firm = c.FILINGMANAGER_NAME.trim();
134	    const key = `${firm}|${s.NAME.trim()}`;
135	    if (seen.has(key)) continue;
136	    seen.add(key);
137	
138	    let ownership: SignatoryRoute['ownership'] = 'individual';
139	    let reason = 'filed by this person as their own contact in a statutory filing they signed';
140	
141	    if (!isNaturalPerson(s.NAME)) {
142	      ownership = 'company';
143	      reason = 'signatory is not a natural person';
144	    } else if ((phoneToFirms.get(p)?.size ?? 0) > 1) {
145	      ownership = 'company';
146	      reason = `number also filed by ${phoneToFirms.get(p)!.size - 1} other filer(s); administrator line`;
147	    } else if ((phoneToPeople.get(p)?.size ?? 0) > 1) {
148	      ownership = 'company';
149	      reason = 'number shared by more than one signatory at this filer';
150	    }
151	
152	    out.push({
153	      firm, accession: s.ACCESSION_NUMBER, person: s.NAME.trim(), title: s.TITLE.trim(),
154	      phone: s.PHONE.trim(), filedOn: c.DATEREPORTED, ownership, reason,
155	    });
156	    addressByAccession.set(s.ACCESSION_NUMBER, {
157	      street: (c.FILINGMANAGER_STREET1 ?? '').trim(),
158	      city: (c.FILINGMANAGER_CITY ?? '').trim(),
159	      stateOrCountry: (c.FILINGMANAGER_STATEORCOUNTRY ?? '').trim(),
160	      zip: (c.FILINGMANAGER_ZIPCODE ?? '').trim(),
161	    });
162	  }
163	  return out;
164	}
165	
166	/**
167	 * Stable entity id for a filer.
168	 *
169	 * Filers found only in the census have no CIK, so they are keyed by their
170	 * normalised name slugged into an id-safe form. Deterministic either way, so a
171	 * re-run upserts the same entity rather than duplicating it.
172	 */
173	export function secEntityId(cik: string): string {
174	  return cik.startsWith('name:')
175	    ? `ent_sec_n_${cik.slice(5).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '')}`
176	    : `ent_sec_${cik}`;
177	}
178	
179	/** One filer, with the routes filed under it. The collector's unit. */
180	export interface FilerUnit {
181	  firm: string;
182	  cik: string;
183	  routes: SignatoryRoute[];
184	  address?: FilerAddress;
185	}
186	
