1	import type { Claim, Gate, GateContext, GateResult } from '@fo/core/contract/index.js';
2	import { checkDerivation } from './derivation.js';
3	
4	/**
5	 * Gate 2 · attribution — the centrepiece.
6	 *
7	 * Question: does the span we cited actually establish this value?
8	 *
9	 * Stage 1 had a check that a quote appeared in its source, and mistook it for a
10	 * check that the quote supported the value. Those are different questions, and
11	 * the gap between them was 93 mis-wired values. This gate asks the second one.
12	 *
13	 * Two kinds of evidence are scored differently, because they make different
14	 * claims about themselves:
15	 *
16	 *   quoting — "the value is written here". Testable now, lexically.
17	 *   pointer — "the value is in the record this names". Testable only by
18	 *             resolving the locator, which is a network call, so it is deferred
19	 *             rather than guessed at.
20	 *
21	 * Deferral is not a loophole. A deferred claim is `skipped`, and the release gate
22	 * treats skipped as not-passed (PTC-2), so a pointer claim cannot reach released
23	 * state until something actually resolves it. An extractor that emitted
24	 * pointer-shaped spans to dodge this gate would produce zero released claims.
25	 */
26	
27	const STOPWORDS = new Set([
28	  'the', 'a', 'an', 'of', 'and', 'or', 'in', 'at', 'on', 'to', 'for', 'by',
29	  'is', 'was', 'are', 'were', 'be', 'as', 'with', 'from', 'this', 'that',
30	  'states', 'page', 'name', 'address', 'suite', 'floor', 'ltd', 'llc', 'limited',
31	]);
32	
33	function tokenize(s: string): string[] {
34	  return s
35	    .toLowerCase()
36	    // keep digits attached to their own token; split ordinals like 57th -> 57
37	    .replace(/(\d)(st|nd|rd|th)\b/g, '$1')
38	    .split(/[^a-z0-9]+/)
39	    .filter(Boolean);
40	}
41	
42	/**
43	 * Tokens that cannot be coincidence: anything containing a digit.
44	 *
45	 * Every one must be present. This is what catches the Kopp address -- the value
46	 * says 701 and 1030, the cited filing says 8400 and 1450, and no amount of
47	 * shared words like "suite" makes that the same address. Prose overlaps by
48	 * accident; house numbers and postcodes do not.
49	 */
50	function hardTokens(tokens: string[]): string[] {
51	  return tokens.filter((t) => /\d/.test(t));
52	}
53	
54	const LOCATOR = /\b(company\s*(number\s*)?\d{6,8}|cik\s*0*\d{6,10}|accession\s*(no\.?\s*)?[\d-]{18,20}|crd\s*\d{5,8})\b/i;
55	
56	export const COVERAGE_THRESHOLD = 0.6;
57	
58	export function checkAttribution(
59	  value: unknown,
60	  spanText: string,
61	  method = '',
62	): { outcome: 'passed' | 'failed' | 'skipped'; detail: string; counterfactual?: unknown } {
63	  // Third evidence kind: the value was computed from what the source says rather
64	  // than written in it. Checked by re-running the named rule, not by exempting
65	  // the claim -- see gates/derivation.ts.
66	  const derived = checkDerivation(value, spanText, method);
67	  if (derived) return derived;
68	
69	  const valueStr = typeof value === 'string' ? value : JSON.stringify(value);
70	  const vTokens = tokenize(valueStr);
71	  const sTokens = new Set(tokenize(spanText));
72	
73	  if (vTokens.length === 0) {
74	    return { outcome: 'failed', detail: 'value has no comparable tokens' };
75	  }
76	
77	  const hard = hardTokens(vTokens);
78	  const missingHard = hard.filter((t) => !sTokens.has(t));
79	
80	  // A value can consist entirely of stopwords: Oregon's state code is "OR",
81	  // which the list filters as the English conjunction. Stripping it leaves
82	  // nothing to compare and the claim fails a check it should have passed.
83	  // Stopwords exist to stop prose overlapping by accident, not to erase short
84	  // values, so when filtering empties the value the raw tokens are used.
85	  const stripped = vTokens.filter((t) => !STOPWORDS.has(t));
86	  const content = stripped.length ? stripped : vTokens;
87	  const present = content.filter((t) => sTokens.has(t));
88	  const coverage = content.length ? present.length / content.length : 0;
89	
90	  const supported = missingHard.length === 0 && coverage >= COVERAGE_THRESHOLD;
91	  if (supported) {
92	    return {
93	      outcome: 'passed',
94	      detail: `span contains the value (${present.length}/${content.length} content tokens, all ${hard.length} hard tokens)`,
95	    };
96	  }
97	
98	  // Not written here. Does the span at least name a record where it would be?
99	  if (LOCATOR.test(spanText)) {
100	    return {
101	      outcome: 'skipped',
102	      detail: 'pointer evidence: locator present, resolution deferred to Band B',
103	    };
104	  }
105	
106	  const why = missingHard.length
107	    ? `span is missing hard token(s) ${missingHard.join(', ')}`
108	    : `content coverage ${(coverage * 100).toFixed(0)}% below ${COVERAGE_THRESHOLD * 100}%`;
109	
110	  return {
111	    outcome: 'failed',
112	    detail: why,
113	    // What would have shipped had this gate not fired: the value, asserted, with
114	    // this span standing behind it. This is the column that proves the gate is
115	    // load-bearing rather than decorative.
116	    counterfactual: { wouldHaveReleased: value, citing: spanText.slice(0, 200) },
117	  };
118	}
119	
120	export const attributionGate: Gate = {
121	  name: 'attribution',
122	  band: 'A',
123	  async evaluate(claim: Claim, ctx: GateContext): Promise<GateResult> {
124	    const establishing = ctx.evidence.find((e) => e.role === 'establishing');
125	    if (!establishing) {
126	      // Structurally impossible through the writer and refused by the database.
127	      // Checked anyway: a claim with no basis must never look merely unproven.
128	      return {
129	        gate: 'attribution',
130	        outcome: 'failed',
131	        band: 'A',
132	        detail: 'no establishing evidence',
133	        counterfactual: { wouldHaveReleased: claim.value, citing: null },
134	      };
135	    }
136	    const r = checkAttribution(claim.value, establishing.spanText, establishing.method);
137	    return { gate: 'attribution', outcome: r.outcome, band: 'A', detail: r.detail, counterfactual: r.counterfactual };
138	  },
139	};

