1	import { db } from './index.js';
2	
3	/**
4	 * Stage 2 read paths for the deployed app.
5	 *
6	 * These use the web app's existing Neon client rather than `connect.ts`.
7	 * `connect.ts` installs a global undici dispatcher to work around a resolver
8	 * fault on the development machine; on Vercel that fault does not exist, and
9	 * calling setGlobalDispatcher inside a serverless function would change fetch
10	 * behaviour for the whole request handler to fix a problem it does not have.
11	 */
12	
13	export interface RunRow {
14	  id: string; job: string; trigger: string; status: string;
15	  started_at: string; ended_at: string | null;
16	  records_touched: number; claims_created: number;
17	  claims_released: number; claims_quarantined: number;
18	  git_sha: string | null;
19	}
20	
21	export async function recentRuns(limit = 20): Promise<RunRow[]> {
22	  return (await db()`
23	    SELECT id, job, trigger, status, started_at, ended_at, records_touched,
24	           claims_created, claims_released, claims_quarantined, git_sha
25	    FROM s2_run ORDER BY started_at DESC LIMIT ${limit}`) as unknown as RunRow[];
26	}
27	
28	export interface ContractStats {
29	  entities: number; qualifying: number;
30	  claims: number; released: number; quarantined: number; held: number;
31	  strictReachable: number; profileAssistedReachable: number;
32	  scheduledRuns: number; windowHours: number | null;
33	}
34	
35	export async function contractStats(): Promise<ContractStats> {
36	  const [e] = (await db()`
37	    SELECT count(*)::int total,
38	           count(*) FILTER (WHERE commercial_state = 'qualifying')::int qualifying,
39	           count(*) FILTER (WHERE strict_reachable)::int strict,
40	           count(*) FILTER (WHERE profile_assisted_reachable)::int assisted
41	    FROM s2_entity`) as unknown as Array<Record<string, number>>;
42	
43	  const [c] = (await db()`
44	    SELECT count(*)::int total,
45	           count(*) FILTER (WHERE status = 'released')::int released,
46	           count(*) FILTER (WHERE status = 'quarantined')::int quarantined,
47	           count(*) FILTER (WHERE status = 'candidate')::int held
48	    FROM s2_claim`) as unknown as Array<Record<string, number>>;
49	
50	  // The operating window is measured from scheduled runs only. A manual
51	  // dispatch cannot evidence unattended operation, so it is excluded here
52	  // rather than quietly counted.
53	  const [w] = (await db()`
54	    SELECT count(*)::int n,
55	           EXTRACT(EPOCH FROM (max(started_at) - min(started_at))) / 3600 AS hours
56	    FROM s2_run WHERE trigger = 'schedule'`) as unknown as Array<{ n: number; hours: number | null }>;
57	
58	  return {
59	    entities: e?.total ?? 0,
60	    qualifying: e?.qualifying ?? 0,
61	    claims: c?.total ?? 0,
62	    released: c?.released ?? 0,
63	    quarantined: c?.quarantined ?? 0,
64	    held: c?.held ?? 0,
65	    strictReachable: e?.strict ?? 0,
66	    profileAssistedReachable: e?.assisted ?? 0,
67	    scheduledRuns: w?.n ?? 0,
68	    windowHours: w?.hours != null ? Math.round(Number(w.hours) * 10) / 10 : null,
69	  };
70	}
71	
72	export interface GateRow { gate: string; outcome: string; n: number }
73	
74	export async function gateOutcomes(): Promise<GateRow[]> {
75	  // The CURRENT verdict per claim and gate. Once a policy bump re-judges the
76	  // file, every claim holds a row per version; counting them all would report
77	  // each claim once per standard it has ever been judged under.
78	  return (await db()`
79	    SELECT gate, outcome, count(*)::int n FROM (
80	      SELECT DISTINCT ON (claim_id, gate) gate, outcome
81	      FROM s2_validation_result
82	      ORDER BY claim_id, gate, policy_version DESC
83	    ) latest
84	    GROUP BY 1, 2 ORDER BY 1, 2`) as unknown as GateRow[];
85	}
86	
87	export interface DecisionRow {
88	  kind: string; rule: string; reason: string; at: string; entity_id: string | null;
89	}
90	
91	/** The staleness and demotion events the operating window has to evidence. */
92	export async function recentDecisions(limit = 25): Promise<DecisionRow[]> {
93	  return (await db()`
94	    SELECT kind, rule, reason, at, entity_id FROM s2_decision_log
95	    WHERE kind IN ('stale', 'quarantine', 'release', 'budget_halt', 'source_circuit')
96	    ORDER BY at DESC LIMIT ${limit}`) as unknown as DecisionRow[];
97	}
98	
99	export interface QuarantineRow {
100	  field: string; value: string; failed: string; reason: string; canonical_name: string;
101	}
102	
103	/**
104	 * What the gates refused, and why. This is the part of the product a customer
105	 * cannot get elsewhere: not the records that passed, but the specific defects
106	 * that were caught before they shipped.
107	 */
108	export async function recentQuarantines(limit = 25): Promise<QuarantineRow[]> {
109	  // A claim that failed two gates has two validation rows, so joining directly
110	  // fans the claim out into duplicate lines. The detail is aggregated into one
111	  // string instead — a reader wants one row per refused value, listing every
112	  // reason it was refused.
113	  return (await db()`
114	    SELECT c.field,
115	           left(c.value_json #>> '{}', 60) AS value,
116	           array_to_string(rd.gates_failed, ', ') AS failed,
117	           left((
118	             SELECT string_agg(vr.detail, ' · ' ORDER BY vr.gate)
119	             FROM s2_validation_result vr
120	             WHERE vr.claim_id = c.id AND vr.outcome IN ('failed', 'error')
121	           ), 140) AS reason,
122	           e.canonical_name
123	    FROM s2_claim c
124	    JOIN s2_release_decision rd ON rd.claim_id = c.id
125	    JOIN s2_entity e ON e.id = c.entity_id
126	    WHERE c.status = 'quarantined'
127	    ORDER BY rd.decided_at DESC LIMIT ${limit}`) as unknown as QuarantineRow[];
128	}

