1	import 'dotenv/config';
2	import { readFileSync } from 'node:fs';
3	import { fileURLToPath } from 'node:url';
4	import { fetchJson, sleep } from '../lib/http.js';
5	
6	/**
7	 * Measured discovery sample (option B).
8	 *
9	 * Runs the widened Companies House search, measures what it would actually
10	 * yield, and writes nothing. The point is to know the duplicate rate, the shell
11	 * rate and the API cost *before* committing a full pool to the pipeline, rather
12	 * than discovering at record 300 that most of them are dormant registrations.
13	 *
14	 * Fragments are name patterns that a family wealth vehicle plausibly registers
15	 * under. They select which companies to look at, never what a company is --
16	 * every candidate still has to pass substance, the gates and the commercial
17	 * floor. Adding a fragment cannot lower the bar; it can only widen the funnel.
18	 */
19	
20	const BASE = 'https://api.company-information.service.gov.uk';
21	
22	/** Stage 1 used these. Kept so the overlap is measurable. */
23	const EXISTING_FRAGMENTS = [
24	  'family office', 'family investment', 'family holdings', 'family capital', 'legacy', 'heritage', 'family trust',
25	];
26	
27	/**
28	 * Explicit family-office terms only.
29	 *
30	 * The first widened set included 'family wealth', 'family services' and
31	 * 'family management', and the sample showed what that actually returns:
32	 * SKEPPER FAMILY WEALTH MANAGEMENT LTD, IFS FAMILY WEALTH ADVISERS LTD,
33	 * REDWOOD FINANCIAL FAMILY WEALTH & ESTATE PLANNERS LIMITED -- independent
34	 * financial advisers and retail wealth practices, not family offices. Importing
35	 * them would hit the record count by putting a different industry in a
36	 * family-office dataset.
37	 *
38	 * These four terms are self-descriptions a firm only adopts if it is claiming to
39	 * be a family office. That claim still establishes nothing on its own: the
40	 * entity is created `unconfirmed` and has to earn its classification from
41	 * evidence like any other.
42	 */
43	const NEW_FRAGMENTS = [
44	  'family office',
45	  'single family office',
46	  'multi family office',
47	  'multi-family office',
48	  'private family office',
49	];
50	
51	/** Stage 1's codes plus adjacent investment-vehicle classifications. */
52	const EXISTING_SIC = ['64205', '64303', '66300', '64209', '70100', '64999'];
53	const NEW_SIC = ['64301', '64302', '64304', '64306', '66190', '70221'];
54	
55	function auth(): Record<string, string> {
56	  const key = process.env.COMPANIES_HOUSE_API_KEY;
57	  if (!key) throw new Error('COMPANIES_HOUSE_API_KEY not set');
58	  return { Authorization: `Basic ${Buffer.from(`${key}:`).toString('base64')}` };
59	}
60	
61	interface SearchHit {
62	  company_number: string;
63	  company_name: string;
64	  company_status: string;
65	  date_of_creation: string;
66	  sic_codes?: string[];
67	}
68	
69	async function search(fragment: string, sic: string): Promise<SearchHit[]> {
70	  const path =
71	    `/advanced-search/companies?company_name_includes=${encodeURIComponent(fragment)}` +
72	    `&sic_codes=${sic}&company_status=active&size=40`;
73	  try {
74	    const r = await fetchJson<{ items?: SearchHit[] }>(`${BASE}${path}`, { headers: auth(), retries: 2 });
75	    return r.items ?? [];
