import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { buildSignatoryRoutes, normFirm, filerUnits } from './sec-signatory.js';
const root = fileURLToPath(new URL('../../../../', import.meta.url));
const routes = buildSignatoryRoutes(root + 'data/sec');
const FAMILY = /\b(FAMILY|FAMILIES)\b/i;

const ind = routes.filter(r => r.ownership === 'individual');
const famNamedWithRoute = new Set(ind.filter(r => FAMILY.test(r.firm)).map(r => r.firm));

const cand = JSON.parse(readFileSync(root + 'data/candidates-sec.json','utf8')) as {entities:Array<{cik:string;legalName:string}>};
const candNames = new Set(cand.entities.map(e => normFirm(e.legalName)).filter(Boolean));

const units = filerUnits(root + 'data/candidates-sec.json', root + 'data/sec');
const unitsWithRoute = units.filter(u => u.routes.some(r => r.ownership === 'individual'));

const byPath = { famOnly:0, candOnly:0, both:0 };
for (const u of unitsWithRoute) {
  const isFam = FAMILY.test(u.firm);
  const isCand = candNames.has(normFirm(u.firm));
  if (isFam && isCand) byPath.both++; else if (isFam) byPath.famOnly++; else byPath.candOnly++;
}
console.log('CENSUS-LEVEL (the "ceiling" measurement)');
console.log(`  filers whose NAME matches FAMILY/FAMILIES and carry an individual route : ${famNamedWithRoute.size}`);
console.log('\nJOB-LEVEL (what the collector selected)');
console.log(`  total filers selected                     : ${units.length}`);
console.log(`  ...of which carry an individual route     : ${unitsWithRoute.length}`);
console.log('\nRECONCILIATION of the selected-with-route figure');
console.log(`  family-named only                         : ${byPath.famOnly}`);
console.log(`  family-named AND in the Stage 1 SEC list   : ${byPath.both}`);
console.log(`  Stage 1 SEC list only (NOT family-named)   : ${byPath.candOnly}`);
console.log(`  -> family-named total                     : ${byPath.famOnly + byPath.both}`);
console.log('\nnon-family-named selected filers (came from the Stage 1 candidate list):');
for (const u of unitsWithRoute.filter(u => !FAMILY.test(u.firm)).slice(0,14)) console.log('   -', u.firm);
