import 'dotenv/config';
import { connect } from './connect.js';
import { assessEntity, POLICY_VERSION } from '../../pipeline/src/release/gate.js';
import type { Claim, Entity } from '@fo/core/contract/index.js';
const sql = connect();
// Recompute commercial_state for every entity from its FULL released set,
// repairing the records the batch-scoped assessment wrongly withheld.
const ents = (await sql`SELECT id FROM s2_entity`) as unknown as Array<{ id: string }>;
