for (const e of ents) {
  const rows = (await sql`SELECT id, entity_id, extraction_event_id, field, value_json, value_type,
    status, confidence, refresh_policy, established_at FROM s2_claim
    WHERE entity_id = ${e.id} AND status='released'`) as unknown as Array<Record<string, any>>;
