    value: r.value_json, valueType: r.value_type, status: r.status, confidence: r.confidence,
    refreshPolicy: r.refresh_policy, establishedAt: new Date(r.established_at),
  })) as Claim[];
  const entity = { id: e.id, canonicalName: e.id, entityType: 'unconfirmed', firstSeenAt: new Date(),
    trustState: 'active', commercialState: 'unassessed', strictReachable: false,
