1	import 'dotenv/config';
2	import { connect } from '../../../db/src/connect.js';
3	import { search, serperUsage } from '../lib/serper.js';
4	import { checkProfileSlug } from '../gates/identity.js';
5	
6	/**
7	 * Measured sample of the verified-profile channel.
8	 *
9	 * Phase 0 measured this at 20% on the Stage 1 fifty and called it the weakest
10	 * projection in the table, because it rested on a 50-record sample. It is now
11	 * the channel that matters most: ADV and Companies House move the 500 and leave
12	 * the 200 untouched, and this is the only measured route that can move it.
13	 *
14	 * The verification is deterministic, not probabilistic (assumption A2): a
15	 * profile counts only when its URL slug encodes the named person's surname. On
16	 * the Stage 1 sample that rejected exactly the two wrong-person links the
17	 * feedback identified -- David Blitzer linked to /in/jonas-cohon, Rodger Riney
18	 * to /in/bobby-w-sandage-jr-phd-69087211.
19	 *
20	 * Writes nothing. Measures and reports.
21	 */
22	
23	const sql = connect();
24	const SAMPLE = Number(process.env.PROFILE_SAMPLE ?? 25);
25	
26	const rows = (await sql`
27	  SELECT DISTINCT ON (e.id) e.id, e.canonical_name, p.value_json #>> '{}' AS person
28	  FROM s2_entity e
29	  JOIN s2_claim p ON p.entity_id = e.id AND p.field LIKE '%fullName' AND p.status = 'released'
30	  WHERE e.commercial_state = 'qualifying' AND NOT e.strict_reachable
31	  ORDER BY e.id`) as unknown as Array<{ id: string; canonical_name: string; person: string }>;
32	
33	// Spread across sources rather than taking the head of the list: the pool is
34	// 98 Companies House, 24 ADV, 17 SEC, and sampling only the first would measure
35	// one source's yield and report it as the channel's.
36	const bySource = new Map<string, typeof rows>();
37	for (const r of rows) {
38	  const k = r.id.startsWith('ent_ch_') ? 'ch' : r.id.startsWith('ent_adv_') ? 'adv' : 'sec';
39	  if (!bySource.has(k)) bySource.set(k, []);
40	  bySource.get(k)!.push(r);
41	}
42	const picked: typeof rows = [];
43	let i = 0;
44	while (picked.length < Math.min(SAMPLE, rows.length)) {
45	  let added = false;
46	  for (const list of bySource.values()) {
47	    if (i < list.length && picked.length < SAMPLE) { picked.push(list[i]!); added = true; }
48	  }
49	  if (!added) break;
50	  i++;
51	}
52	
53	const t0 = Date.now();
54	let searches = 0;
55	const outcome = { verified: 0, wrongPerson: 0, noProfileFound: 0, noResults: 0 };
56	const verified: Array<{ firm: string; person: string; url: string }> = [];
57	const rejected: Array<{ firm: string; person: string; url: string; why: string }> = [];
58	
59	for (const r of picked) {
60	  // Unquoted. The quoted-phrase form returned only the firm's own ADV PDF --
61	  // exact-phrase matching on a name written "SURNAME, FIRST, MIDDLE" matches
62	  // almost nothing on the open web, which produced a false 0% on the first run.
63	  const q = `${r.person} ${r.canonical_name} linkedin`;
64	  let results: Awaited<ReturnType<typeof search>> = [];
65	  try {
66	    results = await search(q, { num: 10 });
67	    searches++;
68	  } catch {
69	    outcome.noResults++;
70	    continue;
71	  }
72	
73	  const profiles = results.filter((x) => /linkedin\.com\/in\//i.test(x.link));
74	  if (!profiles.length) { outcome.noProfileFound++; continue; }
75	
76	  // First profile whose slug encodes the person. A profile that merely appears
77	  // in results for the query is not evidence it belongs to them -- that is the
78	  // exact error Stage 1 shipped twice.
79	  let hit: { link: string; why: string } | null = null;
80	  let firstReject: { link: string; why: string } | null = null;
81	  for (const p of profiles) {
82	    const v = checkProfileSlug(p.link, r.person);
83	    if (v.ok) { hit = { link: p.link, why: v.why }; break; }
84	    if (!firstReject) firstReject = { link: p.link, why: v.why };
85	  }
86	
87	  if (hit) {
88	    outcome.verified++;
89	    verified.push({ firm: r.canonical_name, person: r.person, url: hit.link });
90	  } else {
91	    outcome.wrongPerson++;
92	    if (firstReject) rejected.push({ firm: r.canonical_name, person: r.person, url: firstReject.link, why: firstReject.why });
93	  }
94	}
95	
96	const secs = (Date.now() - t0) / 1000;
97	const yieldRate = picked.length ? outcome.verified / picked.length : 0;
98	const pool = rows.length;
99	
100	console.log(`\n--- VERIFIED-PROFILE SAMPLE ---`);
101	console.log(`addressable pool (qualifying, named principal, no strict route) : ${pool}`);
102	console.log(`sampled                                                        : ${picked.length}`);
103	console.log(`  verified profile (slug encodes the surname)                  : ${outcome.verified}  (${(yieldRate * 100).toFixed(0)}%)`);
104	console.log(`  profile found but slug names someone else                    : ${outcome.wrongPerson}`);
105	console.log(`  no personal profile in results                               : ${outcome.noProfileFound}`);
106	console.log(`  search failed                                                : ${outcome.noResults}`);
107	console.log(`\nsearches issued : ${searches}   serper usage: ${JSON.stringify(serperUsage())}`);
108	console.log(`wall time       : ${secs.toFixed(0)}s  (${picked.length ? (secs / picked.length).toFixed(1) : 0}s per entity)`);
109	console.log(`\n--- PROJECTION ---`);
110	console.log(`profile-assisted routes across the pool of ${pool} : ~${Math.round(pool * yieldRate)}`);
111	console.log(`api calls to run the full pool                    : ~${pool}`);
112	console.log(`estimated wall time                               : ~${((pool * (picked.length ? secs / picked.length : 0)) / 60).toFixed(0)} min`);
113	console.log(`\nNOTE: these are PROFILE-ASSISTED only. Strict reachability is unchanged; a`);
114	console.log(`profile is not a phone or a personal mailbox and never counts as strict.`);
115	
116	console.log(`\nverified (sample):`);
117	for (const v of verified.slice(0, 10)) console.log(`  ${v.person} — ${v.firm}\n      ${v.url}`);
118	console.log(`\nrejected (sample) — the check earning its place:`);
119	for (const v of rejected.slice(0, 6)) console.log(`  ${v.person} — ${v.firm}\n      ${v.url}\n      ${v.why}`);

1	import { createHash, randomUUID } from 'node:crypto';
2	import { readFileSync } from 'node:fs';
3	import type { Collector, Extractor, Observation, Source } from '@fo/core/contract/index.js';
4	import type { OpenExtractionEvent } from '@fo/core/contract/index.js';
5	import { US_STATE_CODES, derivedMethod } from '../gates/derivation.js';
6	
7	/**
8	 * SEC Form ADV — an identity channel, deliberately not a reachability one.
9	 *
10	 * Phase 0 measured Schedule A for contact routes and found zero, because the
11	 * form has no field for individual contact data. That has not changed. What ADV
12	 * gives is the best control-person evidence available to us: a named individual
13	 * with a title, an ownership code and a control-person flag, filed under
14	 * penalty. A 13F signature block cannot match that -- 45% of its signatories are
15	 * compliance and back-office staff.
16	 *
17	 * ### The constraint that shapes everything here
18	 *
19	 * SEC Rule 202(a)(11)(G)-1, the family office rule, EXCLUDES single family
20	 * offices from the definition of investment adviser. They do not register. So
21	 * every firm in this file is a multi-family office or a registered adviser --
22	 * never an SFO -- and no amount of family-office naming changes that.
23	 *
24	 * The classification therefore refuses to guess:
25	 *
26	 *   - `multi_family_office` only where the firm's own registered name says so
27	 *   - `unconfirmed_registered_adviser` otherwise
28	 *   - `family_office` (meaning single) is never assigned from this source
29	 *
30	 * ### Staleness is carried, not hidden
31	 *
32	 * The archive ends 2024-12-31. A 2024 filing date is evidence the firm filed on
33	 * that date, and nothing more -- it is not evidence the firm is registered
34	 * today. So the claim asserted is `latestObservedFilingDate`, a dated fact that
35	 * stays true, rather than a status like "active" that quietly decays.
36	 */
37	
38	export interface AdvRegistrant {
39	  crd: string;
40	  legalName: string;
41	  city: string;
42	  state: string;
43	  street: string;
44	  latestFilingDate: string;
45	  filingId: string;
46	  selfDescribedMultiFamilyOffice: boolean;
47	  controlPersons: Array<{
48	    name: string; title: string; statusAcquired: string;
49	    ownershipCode: string; controlPerson: string;
50	  }>;
51	}
52	
53	export interface AdvFile {
54	  source: string;
55	  archiveCutoff: string;
56	  staleness: string;
57	  registrants: AdvRegistrant[];
58	}
59	
60	export const SEC_ADV_SOURCE: Source = {
61	  id: 'src_sec_adv',
62	  kind: 'sec_adv',
63	  identifier: 'sec.gov/form-adv-archive/20111105-20241231',
64	  baseUrl: 'https://www.sec.gov',
65	  tier: 1,
66	  rateLimitPerMin: 600,
67	  consecutiveFailures: 0,
68	};
69	
70	export function loadAdv(path: string): AdvFile {
71	  return JSON.parse(readFileSync(path, 'utf8')) as AdvFile;
72	}
73	
74	/** Deterministic and CRD-keyed, so a re-run upserts rather than duplicating. */
75	export function advEntityId(crd: string): string {
76	  return `ent_adv_${crd.replace(/[^A-Za-z0-9]/g, '_').toLowerCase()}`;
77	}
78	
79	export function advCollector(registrants: AdvRegistrant[], meta: Pick<AdvFile, 'archiveCutoff' | 'staleness'>): Collector {
80	  return {
81	    kind: 'sec_adv',
82	    async *collect(source: Source, cursor?: string) {
83	      const start = cursor ? registrants.findIndex((r) => r.crd === cursor) + 1 : 0;
84	      for (let i = Math.max(0, start); i < registrants.length; i++) {
85	        const r = registrants[i]!;
86	        const payload = JSON.stringify({ ...r, archiveCutoff: meta.archiveCutoff });
87	        yield {
88	          observation: {
89	            id: `obs_${randomUUID()}`,
90	            sourceId: source.id,
91	            // The firm's own IAPD record: the human-checkable locator for this data.
92	            url: `https://adviserinfo.sec.gov/firm/summary/${r.crd}`,
93	            fetchedAt: new Date(),
94	            contentHash: 'sha256:' + createHash('sha256').update(payload).digest('hex').slice(0, 32),
95	            httpStatus: 200,
96	            notes: meta.staleness,
97	            body: payload,
98	          },
99	          cursor: r.crd,
100	        };
101	      }
102	    },
103	  };
104	}
105	
106	export function advExtractor(): Extractor {
107	  return {
108	    name: 'sec_adv@1',
109	
110	    async extract(observation: Observation, event: OpenExtractionEvent): Promise<void> {
111	      const r = JSON.parse(observation.body ?? '{}') as AdvRegistrant & { archiveCutoff: string };
112	      if (!r.crd) return;
113	      const entityId = advEntityId(r.crd);
114	
115	      const say = (field: string, value: unknown, valueType: string, span: string, method: string,
116	                   policy: 'statutory' | 'volatile' | 'append_only' | 'derived' = 'statutory') => {
117	        if (value === null || value === undefined || String(value).trim() === '') return;
118	        event.assert(
119	          { entityId, field, value, valueType, confidence: 0.9, refreshPolicy: policy },
120	          { observationId: observation.id, spanText: span, method },
121	        );
122	      };
123	      const cited = (path: string, v: unknown) => `${path}: ${String(v)}`;
124	
125	      say('legalName', r.legalName, 'string',
126	        cited('ADV Item 1A (full legal name)', r.legalName),
127	        'the name under which this adviser is registered with the SEC');
128	
129	      say('crd', r.crd, 'string', cited('ADV Item 1D (CRD number)', r.crd),
130	        'the adviser CRD number on the SEC register');
131	
132	      say('street', r.street, 'string', cited('ADV Item 1F1 street', r.street),
133	        'principal office address on the adviser\'s registration');
134	      say('city', r.city, 'string', cited('ADV Item 1F1 city', r.city),
135	        'principal office address on the adviser\'s registration');
136	
137	      if (r.state && US_STATE_CODES.has(r.state.toUpperCase())) {
138	        const span = cited('ADV Item 1F1 state', r.state);
139	        say('region', r.state, 'string', span, 'the state on the adviser\'s registration');
140	        say('country', 'United States', 'string', span, derivedMethod('us_state_to_country', r.state));
141	      }
142	
143	      // A DATE, not a status. "Active" would be an inference that rots the
144	      // moment the archive ages; the date this firm last filed stays true
145	      // forever and lets the reader draw their own conclusion.
146	      say('latestObservedFilingDate', r.latestFilingDate, 'string',
147	        cited('ADV DateSubmitted (most recent filing in the archive)', r.latestFilingDate),
148	        `most recent Form ADV filing in the SEC bulk archive, which ends ${r.archiveCutoff}. ` +
149	        'Evidence the firm filed on this date, not evidence it is registered today.',
150	        'volatile');
151	
152	      // Classification is asserted ONLY where the source states it.
153	      //
154	      // A firm whose registered name says "multi-family office" has told the
155	      // registrar what it is, and that is quotable. `unconfirmed_registered_
156	      // adviser` is the opposite: a statement about the ABSENCE of
157	      // classification evidence. Asserting it as a claim produced 25 rows that
158	      // failed attribution -- correctly, because no filing contains those words
159	      // -- and filled the customer-facing "what the gates refused" list with
160	      // noise that reads like 25 caught defects.
161	      //
162	      // The honest place for that label is the entity's `entity_type`, which the
163	      // job sets. A claim we know cannot be evidenced is not made at all.
164	      if (r.selfDescribedMultiFamilyOffice) {
165	        say('entityClassification', 'multi_family_office', 'string',
166	          cited('ADV Item 1A (full legal name)', r.legalName),
167	          'the adviser\'s own registered name describes it as a multi-family office');
168	      }
169	
170	      // Schedule A individuals: control-person evidence. NOT a contact route --
171	      // Form ADV carries no individual contact field, which Phase 0 measured
172	      // directly. Asserting these as `person_name` only is the point.

