2	import assert from 'node:assert/strict';
3	import { test, after } from 'node:test';
4	
5	import { connect } from './connect.js';
6	import { contractWriter } from './contract-writer.js';
7	
8	/**
9	 * Regression for the scheduled `contract` failure.
10	 *
11	 * The verdict id was `vr_<claimId>_<gate>` — no policy version — so re-judging a
12	 * claim under a new standard collided with the verdict recorded under the old
13	 * one and the whole run died on a primary-key violation. The `ON CONFLICT`
14	 * clause named a different constraint from the primary key, so it could never
15	 * have caught it.
16	 *
17	 * What must hold now: two policy versions produce two rows, and the earlier one
18	 * is preserved. That history is the audit trail showing a claim was quarantined
19	 * under one standard and re-admitted under the next.
20	 */
21	
22	const sql = connect();
23	const db = contractWriter(process.env.DATABASE_URL!);
24	const P = 'vridtest';
25	
26	async function cleanup() {
27	  await sql`DELETE FROM s2_validation_result WHERE claim_id = ${P + '-claim'}`;
28	  await sql`DELETE FROM s2_evidence WHERE claim_id = ${P + '-claim'}`;
29	  await sql`DELETE FROM s2_claim WHERE id = ${P + '-claim'}`;
30	  await sql`DELETE FROM s2_extraction_event WHERE id = ${P + '-ev'}`;
31	  await sql`DELETE FROM s2_observation WHERE id = ${P + '-obs'}`;
32	  await sql`DELETE FROM s2_entity WHERE id = ${P + '-ent'}`;
33	  await sql`DELETE FROM s2_source WHERE id = ${P + '-src'}`;
34	}
35	
36	after(cleanup);
37	
38	test('validation identity · the same claim and gate coexist under two policy versions', async () => {
39	  await cleanup();
40	  await sql`INSERT INTO s2_source (id, kind, identifier, tier) VALUES (${P + '-src'}, 'sec_13f', ${P}, 1)`;
41	  await sql`INSERT INTO s2_observation (id, source_id, url, content_hash)
42	            VALUES (${P + '-obs'}, ${P + '-src'}, 'https://example.test/vr', 'h')`;
43	  await sql`INSERT INTO s2_entity (id, canonical_name) VALUES (${P + '-ent'}, 'VR Identity Test')`;
44	  await sql`INSERT INTO s2_extraction_event (id, observation_id, extractor)
45	            VALUES (${P + '-ev'}, ${P + '-obs'}, 'test')`;
46	  await sql`INSERT INTO s2_claim (id, entity_id, extraction_event_id, field, value_json, value_type)
47	            VALUES (${P + '-claim'}, ${P + '-ent'}, ${P + '-ev'}, 'region', '"OR"'::jsonb, 'string')`;
48	
49	  // Judged under the old standard: quarantined.
50	  await db.recordGateResults(P + '-claim', null, [
51	    { gate: 'attribution', outcome: 'failed', band: 'A', detail: 'content coverage 0% below 60%' },
52	  ], '2025-07-30.1');
53	
54	  // Re-judged under the new standard: passes. This is the exact call that
55	  // brought down the scheduled run.
56	  await db.recordGateResults(P + '-claim', null, [
57	    { gate: 'attribution', outcome: 'passed', band: 'A', detail: 'span contains the value' },
58	  ], '2025-07-31.1');
59	
60	  const rows = (await sql`
61	    SELECT policy_version, outcome, detail FROM s2_validation_result
62	    WHERE claim_id = ${P + '-claim'} AND gate = 'attribution'
63	    ORDER BY policy_version`) as unknown as Array<Record<string, string>>;
64	
65	  assert.equal(rows.length, 2, 'both verdicts must be stored');
66	  assert.equal(rows[0]!.policy_version, '2025-07-30.1');
67	  assert.equal(rows[0]!.outcome, 'failed', 'the earlier verdict must not be overwritten');
68	  assert.equal(rows[1]!.policy_version, '2025-07-31.1');
69	  assert.equal(rows[1]!.outcome, 'passed');
70	});
71	
72	test('validation identity · re-running the same policy version is idempotent', async () => {
73	  // Repeating a policy must update in place rather than accumulate duplicates,
74	  // otherwise a resumed run would double every verdict it re-evaluated.
75	  await db.recordGateResults(P + '-claim', null, [
76	    { gate: 'attribution', outcome: 'passed', band: 'A', detail: 'second pass, same policy' },
77	  ], '2025-07-31.1');
78	
79	  const rows = (await sql`
80	    SELECT detail FROM s2_validation_result
81	    WHERE claim_id = ${P + '-claim'} AND gate = 'attribution'
82	      AND policy_version = '2025-07-31.1'`) as unknown as Array<{ detail: string }>;
83	
84	  assert.equal(rows.length, 1, 'same policy must upsert, not duplicate');
85	  assert.equal(rows[0]!.detail, 'second pass, same policy');
86	});
87	
88	test('validation identity · the id carries the policy version', async () => {
89	  const rows = (await sql`
