91	    WHERE claim_id = ${P + '-claim'} AND gate = 'attribution'
92	    ORDER BY policy_version`) as unknown as Array<{ id: string }>;
93	  assert.match(rows[0]!.id, /2025-07-30\.1$/);
94	  assert.match(rows[1]!.id, /2025-07-31\.1$/);
95	  assert.notEqual(rows[0]!.id, rows[1]!.id);
96	});

