import 'dotenv/config';
import { writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

/**
 * Runs the three official goals against PRODUCTION and preserves everything.
 *
 * The brief asks, for each goal: the exact goal given, the output a user would
 * get from the extended retrieval manually, the agent's structured output, and
 * the raw unedited run log. All four are captured here in one pass so the
 * comparison is between what the same deployed system produced at the same
 * moment, not between an agent run and a hand-written "what you'd otherwise
 * get".
 *
 * Nothing is edited afterwards. If the agent abstains, blocks, or gets something
 * wrong, that is what gets saved -- a trace corrected after the fact is not a
 * trace.
 */

const BASE = process.env.GOALS_BASE ?? 'https://fo-intel-web.vercel.app';
const ATTEMPT = process.env.GOALS_ATTEMPT ?? 'attempt-2';
const OUT = fileURLToPath(new URL(`../../../../docs/goals/${ATTEMPT}/`, import.meta.url));
mkdirSync(OUT, { recursive: true });

interface Goal {
  id: string;
  category: string;
  /** The exact wording submitted. Goal 2 is verbatim from the brief. */
  prompt: string;
  /** The closest equivalent a user could run by hand against the retrieval UI. */
  manual: string;
  why: string;
}

const GOALS: Goal[] = [
  {
    id: 'goal-1-multi-step-commercial-search',
    category: 'Goal 1 · Multi-step commercial search',
    prompt:
      'I am raising a fund and need a prioritised outreach list. Which family offices can I ' +
      'reach by phone at a named individual, how many are there in total, and for the ones you ' +
      'return, which have every value traced to a statutory source rather than an aggregator? ' +
      'Tell me which to approach first and what is missing from each.',
    manual: '/api/shortlist?strict=1&tier=1&limit=25',
    why:
      'No single retrieval call answers this: it needs a filtered shortlist, a separate exact ' +
      'count, per-record evidence grading, and a comparison composed into an outreach order.',
  },
  {
    id: 'goal-2-uncertain-data',
    category: 'Goal 2 · Uncertain-data case (verbatim from the brief)',
    prompt:
      'Identify the family offices in the dataset that are the best fit for a lower-middle-market ' +
      'healthcare services fund seeking limited partners, and tell me how confident you are in each.',
    manual: '/api/shortlist?limit=25',
    why:
      'The dataset holds no mandate, sector or AUM evidence. A strong system says so rather than ' +
      'inferring fit from a firm name. This goal exists to see whether it does.',
  },
  {
    id: 'goal-3-paid-tier',
    category: 'Goal 3 · Paid-tier case',
    prompt:
      'I am about to contact BOSTON FAMILY OFFICE LLC. What does the system hold on them, what ' +
      'evidence backs the contact route, and what did the validation gates refuse to publish ' +
      'about them and why?',
    manual: '/api/shortlist?q=Boston%20Family%20Office&limit=5',
    why:
      'A one-time export cannot tell a buyer what was refused and why. The gate outcomes and the ' +
      'evidence span behind each value are the paid-tier product; the record itself is the free part.',
  },
];

async function post(question: string) {
  const started = new Date().toISOString();
  const t0 = Date.now();
  const res = await fetch(`${BASE}/api/agent`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ question }),
  });
  const body = await res.json();
  return { started, ms: Date.now() - t0, status: res.status, body };
}

async function get(path: string) {
  const res = await fetch(`${BASE}${path}`);
  return { status: res.status, body: await res.json() };
}

const summary: Array<Record<string, unknown>> = [];

for (const g of GOALS) {
  console.log(`\n=== ${g.category} ===`);
  const manual = await get(g.manual);
  const agent = await post(g.prompt);
  const b = agent.body as Record<string, any>;

  // Entity ids the agent actually touched, pulled from the trace rather than
  // from the prose, so the record is of what ran and not what was said.
  const entityIds = new Set<string>();
  for (const t of (b.trace ?? []) as Array<Record<string, any>>) {
    const id = t?.detail?.input?.entityId ?? t?.detail?.scope?.entityId;
    if (typeof id === 'string' && id.startsWith('ent_')) entityIds.add(id);
  }

  const record = {
    goal: g.category,
    goalId: g.id,
    submittedPrompt: g.prompt,
    productionUrl: `${BASE}/api/agent`,
    agentUiUrl: `${BASE}/agent`,
    submittedAtUtc: agent.started,
    latencyMs: agent.ms,
    httpStatus: agent.status,
    whyThisGoal: g.why,

    manualRetrievalEquivalent: {
      url: `${BASE}${g.manual}`,
      httpStatus: manual.status,
      scope: (manual.body as any)?.scope ?? null,
      limits: (manual.body as any)?.limits ?? null,
      results: ((manual.body as any)?.results ?? []).map((r: any) => ({
        entityId: r.entityId, name: r.name, score: r.score,
        contact: r.contact ?? null, matched: r.matched, missing: r.missing,
      })),
    },

    agentAnswer: b.answer ?? null,
    blocked: b.blocked ?? false,
    blockReason: b.blockReason ?? null,
    unhonouredConstraints: b.unhonouredConstraints ?? [],
    abstained: (b.unhonouredConstraints ?? []).length > 0 || b.blocked === true,
    nameCorrections: b.nameCorrections ?? [],
    relevanceAsConfidence: b.relevanceAsConfidence ?? [],
    toolInternalsLeaked: b.toolInternalsLeaked ?? [],
    countsResolvedFromToolOutput: b.countsResolved ?? [],
    toolsUsed: b.toolsUsed ?? [],
    scopePerTool: b.scope ?? [],
    entityIdsUsed: [...entityIds],
    rawTrace: b.trace ?? [],
    error: b.error ?? null,
  };

  writeFileSync(OUT + g.id + '.json', JSON.stringify(record, null, 2));

  console.log(`  submitted   : ${agent.started}  (${agent.ms}ms, HTTP ${agent.status})`);
  console.log(`  blocked     : ${record.blocked}   abstained: ${record.abstained}`);
  console.log(`  relevance-as-confidence: ${JSON.stringify(record.relevanceAsConfidence)}`);
  console.log(`  internals leaked       : ${JSON.stringify(record.toolInternalsLeaked)}`);
  console.log(`  unhonoured  : ${JSON.stringify(record.unhonouredConstraints)}`);
  console.log(`  tools       : ${JSON.stringify(record.toolsUsed)}`);
  console.log(`  entity ids  : ${record.entityIdsUsed.length}`);
  console.log(`  trace steps : ${record.rawTrace.length}`);
  console.log(`  manual scope: ${JSON.stringify(record.manualRetrievalEquivalent.scope)}`);
  console.log(`  answer      : ${String(record.agentAnswer ?? '').slice(0, 300)}`);

  summary.push({
    goal: g.category, file: `docs/goals/${ATTEMPT}/${g.id}.json`,
    submittedAtUtc: agent.started, blocked: record.blocked,
    abstained: record.abstained, tools: record.toolsUsed,
    traceSteps: record.rawTrace.length,
  });
}

writeFileSync(OUT + 'index.json', JSON.stringify({
  attempt: ATTEMPT,
  producedAtUtc: new Date().toISOString(),
  productionBase: BASE,
  note: 'Unedited production output. Nothing was corrected after execution.',
  goals: summary,
}, null, 2));
console.log(`\nwritten: docs/goals/${ATTEMPT}/*.json`);

import { db, shortlist, type ShortlistQuery } from '@fo/db';

/**
 * The agent's tools (spec §8).
 *
 * Every tool returns `{ data, scope, excluded, limits }`. **Scope is mandatory.**
 * It is what lets the agent state in its answer what was searched and what was
 * left out — which Correction 8 requires of every user-visible sentence, and
 * which Stage 1 failed at when it silently answered a narrower question than the
 * one asked.
 *
 * Every tool reads **released claims only**. Candidate, held, quarantined and
 * withheld data is not reachable from here. That is not a filter the agent
 * applies and could forget; it is the only data these queries select.
 */

export interface ToolResult<T> {
  data: T;
  /** what was searched and what matched */
  scope: Record<string, unknown>;
  /** what was deliberately left out, and why */
  excluded: Array<{ reason: string; count: number }>;
  /** what this tool cannot tell you, stated rather than implied */
  limits: string[];
}

export const TOOL_SCHEMAS = [
  {
    name: 'search_firms',
    description:
      'Shortlist firms over released claims, ranked on fit, evidence, freshness and reachability. ' +
      'Returns why each matched and what it is missing.',
    input_schema: {
      type: 'object' as const,
      properties: {
        q: { type: 'string', description: 'substring match on firm name; NOT semantic' },
        requireStrictReachable: { type: 'boolean', description: 'a route reaching a named individual, profiles excluded' },
        requireProfileAssisted: { type: 'boolean', description: 'as above, counting verified personal profiles (assumption A1)' },
        requiredFields: { type: 'array', items: { type: 'string' }, description: 'e.g. ["principal.fullName","principal.phone"]' },
        freshWithinDays: { type: 'number' },
        maxSourceTier: { type: 'number', description: '1 statutory/self, 2 press, 3 aggregator, 4 unranked' },
        limit: { type: 'number' },
      },
    },
  },
  {
    name: 'get_firm',
    description: "One firm's released claims with the evidence span establishing each. Cannot invent absent fields.",
    input_schema: {
      type: 'object' as const,
      properties: { entityId: { type: 'string' } },
      required: ['entityId'],
    },
  },
  {
    name: 'count_matching',
    description: 'Exact count of firms matching a filter. Never an estimate.',
    input_schema: {
      type: 'object' as const,
      properties: {
        requireStrictReachable: { type: 'boolean' },
        requireProfileAssisted: { type: 'boolean' },
        requiredFields: { type: 'array', items: { type: 'string' } },
      },
    },
  },
  {
    name: 'check_evidence',
    description: 'The gate outcomes and evidence for one claim. Asserts nothing beyond what the gates recorded.',
    input_schema: {
      type: 'object' as const,
      properties: { entityId: { type: 'string' }, field: { type: 'string' } },
      required: ['entityId'],
    },
  },
];

export async function search_firms(input: ShortlistQuery): Promise<ToolResult<unknown>> {
  const r = await shortlist({ ...input, limit: Math.min(input.limit ?? 10, 25) });
  return {
    data: r.results.map((x) => ({
      entityId: x.entityId, name: x.name,
      // Renamed from `score`. The agent presented the old name as a confidence
      // score -- "Colony Family Offices, LLC: 0.9993" -- for a healthcare-LP fit
      // question the dataset cannot answer. It is a ranking weight over fit,
      // evidence grade, freshness and reachability. It is not a probability and
      // says nothing about any particular question.
      relevanceScore: x.score,
      strictReachable: x.strictReachable, profileAssistedReachable: x.profileAssistedReachable,
      contact: x.contact ?? null, matched: x.matched, missing: x.missing,
      lastObservedAt: x.lastObservedAt, bestSourceTier: x.bestSourceTier,
    })),
    scope: {
      searched: r.scope.searched,
      matched: r.scope.matched,
      returned: r.scope.returned,
      appliedFilters: r.scope.appliedFilters,
      relevanceScoreMeaning:
        'relevanceScore ranks how well a record matches the FILTERS APPLIED. It is not a ' +
        'confidence, probability, certainty, likelihood or evidence-strength value, and must ' +
        'never be presented as one. Confidence in any specific question comes from whether the ' +
        'fields that question needs are present -- see each result\'s `missing` list.',
      // Spelled out because a model that reads the array length as "the number
      // of firms" understates the answer. Observed doing exactly that: it
      // reported 10 (the page size) when 24 matched.
      countNote:
        `${r.scope.matched} firms matched; the data array holds only the top ${r.scope.returned}. ` +
        `Report ${r.scope.matched} as the count, never the array length.`,
    },
    excluded: r.scope.excluded,
    limits: r.limits,
  };
}

export async function get_firm(input: { entityId: string }): Promise<ToolResult<unknown>> {
  const sql = db();
  const rows = (await sql`
    SELECT c.field, c.value_json #>> '{}' AS value, c.value_type, c.confidence,
           e.span_text, e.method, o.url, s.tier, o.fetched_at
    FROM s2_claim c
    JOIN s2_evidence e ON e.claim_id = c.id AND e.role = 'establishing'
    JOIN s2_observation o ON o.id = e.observation_id
    JOIN s2_source s ON s.id = o.source_id
    WHERE c.entity_id = ${input.entityId} AND c.status = 'released'
    ORDER BY c.field`) as unknown as Array<Record<string, any>>;

  const ent = (await sql`
    SELECT canonical_name, entity_type, commercial_state, strict_reachable, profile_assisted_reachable
    FROM s2_entity WHERE id = ${input.entityId}`) as unknown as Array<Record<string, any>>;

  // Non-released claims are counted but never shown. The agent is told they
  // exist so it can say "some values did not pass" rather than implying the
  // record is simply thin -- but it cannot read them.
  const [withheld] = (await sql`
    SELECT count(*) FILTER (WHERE status='quarantined')::int quarantined,
           count(*) FILTER (WHERE status='candidate')::int held
    FROM s2_claim WHERE entity_id = ${input.entityId}`) as unknown as Array<Record<string, number>>;

  return {
    data: {
      entity: ent[0] ?? null,
      claims: rows.map((r) => ({
        field: r.field, value: r.value, valueType: r.value_type, confidence: r.confidence,
        evidence: { span: r.span_text, method: r.method, url: r.url, sourceTier: r.tier, observedAt: r.fetched_at },
      })),
    },
    scope: { entityId: input.entityId, releasedClaims: rows.length },
    excluded: [
      ...(withheld?.quarantined ? [{ reason: 'claims quarantined by a gate (not readable here)', count: withheld.quarantined }] : []),
      ...(withheld?.held ? [{ reason: 'claims held pending an unresolved check', count: withheld.held }] : []),
    ],
    limits: [
      'Only released claims are returned. A field absent here is a field this system does not have — not a field the firm lacks.',
      'The evidence span is the exact text read. It is not a summary and has not been paraphrased.',
    ],
  };
}

export async function count_matching(input: {
  requireStrictReachable?: boolean; requireProfileAssisted?: boolean; requiredFields?: string[];
}): Promise<ToolResult<unknown>> {
  const r = await shortlist({ ...input, limit: 1 });
  return {
    data: { count: r.scope.matched },
    scope: { searched: r.scope.searched, appliedFilters: r.scope.appliedFilters },
    excluded: r.scope.excluded,
    limits: ['An exact count over released claims at this moment. Not an estimate and not a projection.'],
  };
}

/**
 * The fields the extractors actually emit.
 *
 * `check_evidence` previously accepted any string. Asked about a contact route
 * the agent invented `contactRoute`, received an empty successful result, and
 * concluded "validation gates did not refuse to publish any information" -- a
 * claim about absence drawn from a query that could not have found anything.
 * An unknown field now fails closed.
 */
export const SUPPORTED_EVIDENCE_FIELDS = [
  'legalName', 'companyNumber', 'companyStatus', 'incorporatedOn', 'cik', 'crd',
  'street', 'city', 'region', 'postcode', 'country',
  'principal.fullName', 'principal.title', 'principal.phone', 'principal.linkedinUrl',
  'officer.fullName', 'officer.postalAddress', 'controller.entityName',
  'latestObservedFilingDate', 'entityClassification',
] as const;

export async function check_evidence(input: { entityId: string; field?: string }): Promise<ToolResult<unknown>> {
  // Validated before the connection is opened: an unknown field is a caller
  // error, and answering it should not require a database at all.
  if (input.field && !SUPPORTED_EVIDENCE_FIELDS.includes(input.field as never)) {
    // A validation error, not an empty result. Zero rows for a field that does
    // not exist is not evidence that nothing was withheld.
    return {
      data: { error: 'unknown_field', requested: input.field, supportedFields: SUPPORTED_EVIDENCE_FIELDS },
      scope: { entityId: input.entityId, field: input.field, validationError: true },
      excluded: [],
      limits: [
        `"${input.field}" is not a field in this dataset, so nothing was checked.`,
        'This result says NOTHING about whether values were withheld for this firm. ' +
        'Re-run with a supported field, or call get_firm first to see which fields exist.',
      ],
    };
  }

  const sql = db();

  // Only the verdict under the newest policy the claim was judged under. An
  // older verdict is history, not the system's current position, and returning
  // both would let the agent quote a superseded outcome as current.
  const rows = (await sql`
    SELECT c.field, c.status, vr.gate, vr.outcome, vr.detail, vr.policy_version
    FROM s2_claim c
    LEFT JOIN LATERAL (
      SELECT DISTINCT ON (v.gate) v.gate, v.outcome, v.detail, v.policy_version
      FROM s2_validation_result v
      WHERE v.claim_id = c.id
      ORDER BY v.gate, v.policy_version DESC
    ) vr ON TRUE
    WHERE c.entity_id = ${input.entityId}
      AND (${input.field ?? null}::text IS NULL OR c.field = ${input.field ?? null})
    ORDER BY c.field, vr.gate`) as unknown as Array<Record<string, any>>;

  return {
    data: rows.map((r) => ({
      field: r.field, claimStatus: r.status, gate: r.gate,
      outcome: r.outcome, detail: r.detail, policyVersion: r.policy_version,
    })),
    scope: { entityId: input.entityId, field: input.field ?? 'all', rows: rows.length },
    excluded: [],
    limits: [
      'Reports what the gates recorded and nothing beyond it. A passed gate means that specific check passed, not that the value is true.',
      "`skipped` is not `passed`. A skipped gate means the check did not run.",
    ],
  };
}

export const TOOLS: Record<string, (input: any) => Promise<ToolResult<unknown>>> = {
  search_firms, get_firm, count_matching, check_evidence,
};

import assert from 'node:assert/strict';
import { test } from 'node:test';

import { auditClaims, confidenceBlockMessage } from './claims-guard.js';
import { SUPPORTED_EVIDENCE_FIELDS, check_evidence } from './tools.js';

/**
 * Regressions for the three defects the first production goal run exposed.
 * The strings below are the exact text production produced, kept in
 * docs/goals/attempt-1/.
 */

const SCORES = [0.9993, 0.9984, 0.9975];

test('claims · THE GOAL 2 FAILURE: a relevance score presented as confidence is caught', () => {
  const answer =
    'The dataset cannot express market size, investment sector or mandate. Instead, the search ' +
    'returned 80 family offices. Confidence scores are Colony Family Offices, LLC: 0.9993, ' +
    'RiverGlades Family Offices LLC: 0.9993, Allie Family Office LLC: 0.9984.';
  const a = auditClaims(answer, SCORES);
  assert.ok(a.relevanceAsConfidence.length > 0, 'must catch the relabelled score');
  assert.ok(a.relevanceAsConfidence.some((r) => r.value === 0.9993));
  assert.match(confidenceBlockMessage(a), /ranks how well a record matched/);
});

test('claims · the same score as a percentage is also caught', () => {
  // Converting 0.9993 to "99.93% confident" is the same claim in another form.
  const a = auditClaims('We are 99.93% confident in Colony Family Offices, LLC.', SCORES);
  assert.ok(a.relevanceAsConfidence.length > 0);
});

test('claims · stating the relevance score AS a relevance score is allowed', () => {
  // The number is not forbidden — mislabelling it is.
  const a = auditClaims(
    'Ranked by relevance to the filters applied, Colony Family Offices, LLC scores 0.9993.',
    SCORES,
  );
  assert.deepEqual(a.relevanceAsConfidence, []);
});

test('claims · honest low-confidence wording passes', () => {
  const a = auditClaims(
    'I cannot confidently determine fit for a healthcare services fund: the dataset holds no ' +
    'mandate, sector or allocation evidence for any of these firms, so my confidence is low.',
    SCORES,
  );
  assert.deepEqual(a.relevanceAsConfidence, []);
  assert.deepEqual(a.internals, []);
});

test('claims · THE GOAL 3 LEAK: tool internals in buyer-facing prose are caught', () => {
  const answer =
    'Validation gates did not refuse to publish any information, with 0 rows and 0 data.';
  const a = auditClaims(answer, SCORES);
  assert.ok(a.internals.length > 0, 'must catch "0 rows" / "0 data"');
});

test('claims · ordinary business prose is not mistaken for internals', () => {
  const a = auditClaims(
    'BOSTON FAMILY OFFICE LLC holds nine released values, including a phone number that reaches ' +
    'George Beal, its Managing Partner. Nothing was withheld for this firm.',
    SCORES,
  );
  assert.deepEqual(a.internals, []);
  assert.deepEqual(a.relevanceAsConfidence, []);
});

test('evidence fields · THE GOAL 3 DEFECT: an unknown field fails closed', async () => {
  // "contactRoute" does not exist. Previously this returned an empty successful
  // result, which the agent read as "nothing was withheld".
  const r = await check_evidence({ entityId: 'ent_sec_n_boston_family_office', field: 'contactRoute' });
  const data = r.data as Record<string, unknown>;
  assert.equal(data.error, 'unknown_field');
  assert.equal((r.scope as Record<string, unknown>).validationError, true);
  assert.ok(r.limits.some((l) => /says NOTHING about whether values were withheld/i.test(l)));
});

test('evidence fields · the supported list covers the fields the extractors emit', () => {
  for (const f of ['principal.phone', 'principal.fullName', 'principal.linkedinUrl',
                   'officer.postalAddress', 'legalName', 'country']) {
    assert.ok(SUPPORTED_EVIDENCE_FIELDS.includes(f as never), `${f} must be supported`);
  }
  assert.ok(!SUPPORTED_EVIDENCE_FIELDS.includes('contactRoute' as never));
});

