1	/**
2	 * Two deterministic output guards, both written against real production failures.
3	 *
4	 * ### 1. A relevance score is not a confidence score
5	 *
6	 * Asked the verbatim Goal 2 question — best fit for a lower-middle-market
7	 * healthcare services fund seeking LPs — the agent correctly said the dataset
8	 * cannot express sector, mandate or market size, and then wrote:
9	 *
10	 *   "Confidence scores are Colony Family Offices, LLC: 0.9993"
11	 *
12	 * That number is the shortlist's ranking weight over fit, evidence grade,
13	 * freshness and reachability. Colony holds no sector, AUM or mandate claim, so
14	 * 99.93% confidence in a healthcare-LP fit rests on nothing. The answer
15	 * contradicted its own first sentence.
16	 *
17	 * Renaming the field helps and does not settle it, because the model can still
18	 * relabel. This is the part that cannot be talked past.
19	 *
20	 * ### 2. Tool internals are not buyer-facing language
21	 *
22	 * "Validation gates did not refuse to publish any information, with 0 rows and
23	 * 0 data." A non-technical buyer cannot read that, and the brief requires every
24	 * user-visible state to be understandable to one.
25	 */
26	
27	const CONFIDENCE_WORD =
28	  /\b(confidence|confident|probability|probable|certainty|certain|likelihood|likely|evidence strength|strength of evidence|assurance|reliability score)\b/i;
29	
30	/** Tool-shaped phrasing that must never reach a customer. */
31	const TOOL_INTERNALS = [
32	  /\b\d+\s+rows?\b/i,
33	  /\b(rows?|dataLength|releasedClaims|excludedTotal|appliedFilters|entityId|value_?type|claim_?id|policy_?version)\b/,
34	  /\b0\s+data\b/i,
35	  /\bnull\b/,
36	  /\bundefined\b/,
37	  /\[\[|\]\]/,
38	];
39	
40	export interface ClaimsAudit {
41	  /** relevance values presented as confidence */
42	  relevanceAsConfidence: Array<{ value: number; context: string }>;
43	  /** tool internals leaking into prose */
44	  internals: string[];
45	}
46	
47	/**
48	 * Does the answer present a relevance score as a confidence?
49	 *
50	 * Deliberately lexical. Asking a model whether an answer conflates the two
51	 * reintroduces the judgement that failed in the first place.
52	 *
53	 * A number counts as a relevance score if it matches one the tools returned,
54	 * either as the raw value (0.9993) or as a percentage (99.93). It counts as
55	 * *presented as confidence* if a confidence word appears within 120 characters —
56	 * enough to span "Confidence scores are X: 0.9993, Y: 0.9984" without reaching
57	 * into an unrelated sentence.
58	 */
59	export function auditClaims(answer: string, relevanceScores: number[]): ClaimsAudit {
60	  const relevanceAsConfidence: Array<{ value: number; context: string }> = [];
61	  const seen = new Set<number>();
62	
63	  if (relevanceScores.length) {
64	    const wanted = new Map<string, number>();
65	    for (const s of relevanceScores) {
66	      wanted.set(s.toFixed(4).replace(/0+$/, '').replace(/\.$/, ''), s);
67	      wanted.set(s.toFixed(3), s);
68	      wanted.set(s.toFixed(2), s);
69	      wanted.set((s * 100).toFixed(2).replace(/\.?0+$/, ''), s);
70	      wanted.set((s * 100).toFixed(1).replace(/\.0$/, ''), s);
71	      wanted.set(String(Math.round(s * 100)), s);
72	    }
73	
74	    for (const m of answer.matchAll(/\d+(?:\.\d+)?/g)) {
75	      const raw = m[0];
76	      const score = wanted.get(raw) ?? wanted.get(raw.replace(/0+$/, '').replace(/\.$/, ''));
77	      if (score === undefined) continue;
78	      const at = m.index ?? 0;
79	      const window = answer.slice(Math.max(0, at - 120), Math.min(answer.length, at + 60));
80	      if (CONFIDENCE_WORD.test(window) && !seen.has(score)) {
81	        seen.add(score);
82	        relevanceAsConfidence.push({ value: score, context: window.replace(/\s+/g, ' ').trim() });
83	      }
84	    }
85	  }
86	
87	  const internals: string[] = [];
88	  for (const re of TOOL_INTERNALS) {
89	    const hit = re.exec(answer);
90	    if (hit && !internals.includes(hit[0])) internals.push(hit[0]);
91	  }
92	
93	  return { relevanceAsConfidence, internals };
94	}
95	
96	/**
97	 * What a blocked answer says instead.
98	 *
99	 * It states the failure rather than silently softening the wording, because a
100	 * quietly rewritten answer is indistinguishable from one that was right.
101	 */
102	export function confidenceBlockMessage(audit: ClaimsAudit): string {
