"""          # Two budgets, and whichever binds first ends the run cleanly with a
          # checkpoint and a logged decision. 250 units is the cheap case; the
          # 40-minute wall clock is what actually holds when the pool is dense
          # with substantive companies, which cost three API calls each.
          MAX_UNITS: '250'
          MAX_RUN_MS: '2400000'""")
y = y.replace("    timeout-minutes: 30", "    timeout-minutes: 50")
w.write_text(y)
print('wall-clock budget added; runner timeout 50m > job budget 40m')
