    'psc.items[].name + company_profile.company_name: MR JOHN SMITH || SMITH FAMILY OFFICE LIMITED';
  const method = derivedMethod('family_surname_control', 'MR JOHN SMITH || SMITH FAMILY OFFICE LIMITED');

