    await fn(run);
    await run.finish('completed', cost());
  } catch (err) {
    run.failures.push({ fatal: true, message: err instanceof Error ? err.message : String(err) });
    await run.log('error', 'run_failed', { message: err instanceof Error ? err.message : String(err) });
