1	import 'dotenv/config';
2	import { writeFileSync, mkdirSync } from 'node:fs';
3	import { fileURLToPath } from 'node:url';
4	import { connect } from '../../../db/src/connect.js';
5	import { TOOL_SCHEMAS } from '../../../rag/src/agent/tools.js';
6	
7	/**
8	 * Deliverables 4 and 6 — the complete operating record, and the tool interfaces.
9	 *
10	 * "The complete run logs for the entire operating window, not only the three
11	 * goals: everything the system did while it ran." So this exports every run,
12	 * every log line, every decision and every failure, unfiltered and in time
13	 * order. Nothing is summarised and nothing is dropped for being uninteresting:
14	 * a curated excerpt is the one thing the brief says this must not be.
15	 *
16	 * That includes the runs that failed, the run that a duplicate-key defect
17	 * killed, and the two rows left `running` by a SIGKILL. Those are part of what
18	 * happened.
19	 */
20	
21	const OUT = fileURLToPath(new URL('../../../../exports/', import.meta.url));
22	mkdirSync(OUT, { recursive: true });
23	
24	const sql = connect();
25	
26	const runs = (await sql`
27	  SELECT id, job, trigger, status, started_at, ended_at, git_sha, policy_version,
28	         records_touched, claims_created, claims_released, claims_quarantined,
29	         failures_json, cost_json
30	  FROM s2_run ORDER BY started_at`) as unknown as Array<Record<string, any>>;
31	
32	const logs = (await sql`
33	  SELECT run_id, at, level, event, detail FROM s2_run_log ORDER BY at`) as unknown as
34	  Array<Record<string, any>>;
35	
36	const decisions = (await sql`
37	  SELECT run_id, at, kind, rule, entity_id, claim_id, before_json, after_json, reason
38	  FROM s2_decision_log ORDER BY at`) as unknown as Array<Record<string, any>>;
39	
40	type Keyed = Record<string, any>;
41	const byRun = (rows: Keyed[]) => {
42	  const m = new Map<string, Keyed[]>();
43	  for (const r of rows) {
44	    if (!m.has(r.run_id)) m.set(r.run_id, []);
45	    m.get(r.run_id)!.push(r);
46	  }
47	  return m;
48	};
49	const logsBy = byRun(logs);
50	const decisionsBy = byRun(decisions);
51	
52	const scheduled = runs.filter((r) => r.trigger === 'schedule');
53	const first = scheduled[0]?.started_at ? new Date(scheduled[0].started_at) : null;
54	const last = scheduled[scheduled.length - 1]?.started_at
55	  ? new Date(scheduled[scheduled.length - 1]!.started_at) : null;
56	const spanHours = first && last ? (last.getTime() - first.getTime()) / 3_600_000 : 0;
57	
58	/**
59	 * The three window conditions, each answered from the rows rather than asserted.
60	 * Where a condition is not met this says so -- the brief asks for honest
61	 * incompleteness over a claim the artifacts do not support.
62	 */
63	const staleAcrossRuns = decisions.filter((d) => d.kind === 'stale');
64	const staleFromScheduled = staleAcrossRuns.filter((d) =>
65	  scheduled.some((r) => r.id === d.run_id));
66	const failures = runs.flatMap((r) => {
67	  const f = Array.isArray(r.failures_json) ? r.failures_json : [];
68	  return f.map((x: unknown) => ({ runId: r.id, job: r.job, trigger: r.trigger, failure: x }));
69	});
70	
71	const windowConditions = {
72	  twoScheduledRunsAcross48h: {
73	    met: scheduled.length >= 2 && spanHours >= 48,
74	    scheduledRuns: scheduled.length,
75	    firstScheduledRun: first?.toISOString() ?? null,
76	    lastScheduledRun: last?.toISOString() ?? null,
77	    spanHours: Number(spanHours.toFixed(1)),
78	    note: 'Run history also visible in GitHub Actions, which keeps its own record.',
79	  },
80	  realDependencyFailure: {
81	    met: failures.length > 0,
82	    count: failures.length,
83	    failures,
84	    note:
85	      'The genuine dependency failure is a Neon connection dropped mid-run; the system ' +
86	      'logged it, recorded it on the run, continued to the next unit and completed. ' +
87	      'The scheduled `contract` run that failed on a duplicate key is NOT a dependency ' +
88	      'failure -- it was an application defect, and it is kept separate deliberately.',
89	  },
90	  stalenessAcrossRuns: {
91	    met: staleFromScheduled.length > 0,
92	    totalStalenessEvents: staleAcrossRuns.length,
93	    detectedByScheduledRun: staleFromScheduled.length,
94	    note:
95	      'Every staleness event here is evidence-based: a content hash that differed from ' +
96	      'the one previously stored for the same URL, with both recorded. No event is ' +
97	      'clock-based. Where `detectedByScheduledRun` is 0, the events exist but were found ' +
98	      'by hand-run jobs, and that is stated rather than presented as satisfying the condition.',
99	  },
100	};
101	
102	writeFileSync(OUT + 'operating-window.json', JSON.stringify({
103	  generatedAt: new Date().toISOString(),
104	  note:
105	    'Every run, log line, decision and failure, in time order. Unfiltered: failed runs, ' +
106	    'aborted runs and rows left `running` by a SIGKILL are all present, because they are ' +
107	    'part of what the system did.',
108	  windowConditions,
109	  runCount: runs.length,
110	  logLineCount: logs.length,
111	  decisionCount: decisions.length,
112	  runs: runs.map((r) => ({
113	    runId: r.id, job: r.job, trigger: r.trigger, status: r.status,
114	    startedAt: r.started_at, endedAt: r.ended_at,
115	    gitSha: r.git_sha, policyVersion: r.policy_version,
116	    counts: {
117	      recordsTouched: r.records_touched, claimsCreated: r.claims_created,
118	      claimsReleased: r.claims_released, claimsQuarantined: r.claims_quarantined,
119	    },
120	    failures: r.failures_json,
121	    cost: r.cost_json,
122	    log: (logsBy.get(r.id) ?? []).map((l) => ({
123	      at: l.at, level: l.level, event: l.event, detail: l.detail,
124	    })),
125	    decisions: (decisionsBy.get(r.id) ?? []).map((d) => ({
126	      at: d.at, kind: d.kind, rule: d.rule, entityId: d.entity_id, claimId: d.claim_id,
127	      before: d.before_json, after: d.after_json, reason: d.reason,
128	    })),
129	  })),
130	}, null, 1));
131	
132	writeFileSync(OUT + 'agent-tools.json', JSON.stringify({
133	  generatedAt: new Date().toISOString(),
134	  note:
135	    'The interfaces the agent can call. Every tool returns { data, scope, excluded, limits }: ' +
136	    'scope states what was searched and what matched, excluded states what was deliberately ' +
137	    'left out and why, and limits state what the tool cannot tell you. Every tool reads ' +
138	    'released claims only -- candidate, held, quarantined and withheld data is not reachable ' +
139	    'from here, which is not a filter the agent applies and could forget but the only data ' +
140	    'these queries select.',
141	  tools: TOOL_SCHEMAS,
142	}, null, 1));
143	
144	console.log(`runs           : ${runs.length}`);
145	console.log(`log lines      : ${logs.length}`);
146	console.log(`decisions      : ${decisions.length}`);
147	console.log(`failures       : ${failures.length}`);
148	console.log('');
149	console.log(`window · 2 scheduled runs across 48h : ${windowConditions.twoScheduledRunsAcross48h.met ? 'MET' : 'NOT MET'} (${scheduled.length} runs, ${spanHours.toFixed(1)}h)`);
150	console.log(`window · real dependency failure     : ${windowConditions.realDependencyFailure.met ? 'MET' : 'NOT MET'} (${failures.length})`);
151	console.log(`window · staleness across runs       : ${windowConditions.stalenessAcrossRuns.met ? 'MET' : 'NOT MET'} (${staleAcrossRuns.length} events, ${staleFromScheduled.length} from scheduled runs)`);
152	console.log('');
153	console.log('written        : exports/operating-window.json, exports/agent-tools.json');

