1	import 'dotenv/config';
2	import { writeFileSync, mkdirSync } from 'node:fs';
3	import { fileURLToPath } from 'node:url';
4	import { connect } from '../../../db/src/connect.js';
5	
6	/**
7	 * Check that every URL the dataset cites still resolves.
8	 *
9	 * Each of the 958 URLs is where a value was actually read, so a dead one means a
10	 * reviewer cannot check that value for themselves. This fetches all of them and
11	 * writes the outcome per URL.
12	 *
13	 * Three source classes behave differently and the report keeps them apart:
14	 *
15	 *   - **Companies House** is an authenticated API. Unauthenticated it returns
16	 *     401, which says nothing about the URL, so the key is sent.
17	 *   - **SEC** is public but rejects requests without a declared User-Agent.
18	 *   - **LinkedIn blocks automated requests by design**, typically with 999 or a
19	 *     login wall. A non-200 from LinkedIn is therefore NOT evidence that the
20	 *     profile is gone, and it is reported separately rather than counted as a
21	 *     failure -- calling it one would misstate the file's condition in the
22	 *     direction that looks worse, which is no better than the reverse.
23	 */
24	
25	const OUT = fileURLToPath(new URL('../../../../exports/', import.meta.url));
26	mkdirSync(OUT, { recursive: true });
27	const sql = connect();
28	
29	const rows = (await sql`
30	  SELECT DISTINCT o.url, s.identifier AS source, s.tier
31	  FROM s2_observation o
32	  JOIN s2_source s ON s.id = o.source_id
33	  WHERE EXISTS (
34	    SELECT 1 FROM s2_extraction_event xe
35	    JOIN s2_claim c ON c.extraction_event_id = xe.id AND c.status = 'released'
36	    WHERE xe.observation_id = o.id)
37	  ORDER BY o.url`) as unknown as Array<{ url: string; source: string; tier: number }>;
38	
39	const CH_KEY=[REDACTED] ?? '';
40	const UA = process.env.SEC_USER_AGENT ?? 'fo-intel research contact@example.com';
41	
42	function headersFor(url: string): Record<string, string> {
43	  if (url.includes('company-information.service.gov.uk')) {
44	    return { Authorization: `Basic ${Buffer.from(`${CH_KEY}:`).toString('base64')}` };
45	  }
46	  return { 'User-Agent': UA, Accept: '*/*' };
47	}
48	
49	const isLinkedIn = (u: string) => /(^|\.)linkedin\.com/.test(new URL(u).host);
50	
51	interface Result { url: string; source: string; tier: number; status: number | string; ok: boolean; note: string }
52	const results: Result[] = [];
53	let done = 0;
54	
55	async function check(r: { url: string; source: string; tier: number }): Promise<Result> {
56	  const ac = new AbortController();
57	  const timer = setTimeout(() => ac.abort(), 20_000);
58	  try {
59	    const res = await fetch(r.url, { headers: headersFor(r.url), redirect: 'follow', signal: ac.signal });
60	    const li = isLinkedIn(r.url);
61	    return {
62	      url: r.url, source: r.source, tier: r.tier, status: res.status,
63	      // A LinkedIn non-200 is a bot wall, not a dead link, and is not counted
64	      // as a failure either way -- only as "could not be checked from here".
65	      // 429 is LinkedIn's rate limiter answering a script, and 999 is its bot
66	      // wall. Neither says the profile is gone -- an earlier run counted 268
67	      // of them as broken links, which overstated the file's decay from the
68	      // opposite direction to the usual mistake.
69	      ok: res.ok || (li && [999, 403, 401, 429].includes(res.status)),
70	      note: res.ok ? 'resolves'
71	        : li ? `LinkedIn ${res.status}: rate limit or bot wall, not a dead profile; not checkable from a script`
72	        : `HTTP ${res.status}`,
73	    };
74	  } catch (err) {
75	    const li = isLinkedIn(r.url);
76	    return {
77	      url: r.url, source: r.source, tier: r.tier, status: 'error', ok: li,
78	      note: li ? 'LinkedIn blocks automated requests; not checkable from a script'
79	               : (err instanceof Error ? err.message : String(err)),
80	    };
81	  } finally {
82	    clearTimeout(timer);
83	    if (++done % 100 === 0) console.log(`  ...${done}/${rows.length}`);
84	  }
85	}
86	
87	// Modest concurrency: these are other people's servers and one of them rate
88	// limits at 600 requests per five minutes.
89	const CONCURRENCY = 6;
90	const queue = [...rows];
91	await Promise.all(Array.from({ length: CONCURRENCY }, async () => {
92	  for (;;) {
93	    const next = queue.shift();
94	    if (!next) return;
95	    results.push(await check(next));
96	    await new Promise((r) => setTimeout(r, 120));
97	  }
98	}));
99	
100	const esc = (v: unknown) => {
101	  const s = String(v ?? '');
102	  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
103	};
104	writeFileSync(OUT + 'url-check.csv',
105	  ['url,source,tier,httpStatus,ok,note',
106	   ...results.sort((a, b) => a.url.localeCompare(b.url))
107	     .map((r) => [r.url, r.source, r.tier, r.status, r.ok, r.note].map(esc).join(','))].join('\n') + '\n');
108	
109	const byHost = new Map<string, { ok: number; bad: number; blocked: number }>();
110	for (const r of results) {
111	  const h = new URL(r.url).host;
112	  const e = byHost.get(h) ?? { ok: 0, bad: 0, blocked: 0 };
113	  if (r.note.startsWith('LinkedIn blocks')) e.blocked++;
114	  else if (r.ok) e.ok++;
115	  else e.bad++;
116	  byHost.set(h, e);
117	}
118	
119	console.log('\nURL CHECK');
120	console.log(`  URLs checked : ${results.length}\n`);
121	console.log(`  ${'host'.padEnd(42)} ${'ok'.padStart(5)} ${'failed'.padStart(7)} ${'bot-walled'.padStart(11)}`);
122	for (const [h, e] of [...byHost].sort((a, b) => (b[1].ok + b[1].bad + b[1].blocked) - (a[1].ok + a[1].bad + a[1].blocked))) {
123	  console.log(`  ${h.padEnd(42)} ${String(e.ok).padStart(5)} ${String(e.bad).padStart(7)} ${String(e.blocked).padStart(11)}`);
124	}
125	const broken = results.filter((r) => !r.ok);
126	console.log(`\n  genuinely broken: ${broken.length}`);
127	for (const b of broken.slice(0, 15)) console.log(`    ${b.status}  ${b.url}`);
128	console.log('\nwritten: exports/url-check.csv');

