    ({ question } = await req.json());
  } catch {
    return NextResponse.json({ error: 'malformed request' }, { status: 400 });
  }

  if (typeof question !== 'string' || question.trim().length < 3) {
    return NextResponse.json({ error: 'Please enter a question.' }, { status: 400 });
