const rows = await sql`
  SELECT e.id, e.canonical_name,
    array_agg(DISTINCT c.value_json #>> '{}') FILTER (WHERE c.field='principal.fullName') people,
    EXISTS(SELECT 1 FROM s2_claim x WHERE x.entity_id=e.id AND x.field='entityClassification' AND x.status='released') classified
  FROM s2_entity e LEFT JOIN s2_claim c ON c.entity_id=e.id AND c.status='released'
  WHERE e.merged_into_id IS NULL AND e.commercial_state='qualifying'
  GROUP BY e.id, e.canonical_name` as unknown as Array<{id:string;canonical_name:string;people:string[]|null;classified:boolean}>;

const NOT_FAMILY = new Set(['family','office','offices','holdings','holding','investment','investments',
  'capital','partners','group','limited','ltd','llp','plc','company','trust','trustees','management',
  'ventures','properties','property','estates','assets','wealth','advisors','advisers','services',
  'international','the','and','mr','mrs','ms','miss','dr','sir','lord','lady','prof']);
const surnameOf=(p:string)=>{const h=p.includes(',')?p.split(',')[0]!:p;
  const t=h.toLowerCase().replace(/[^a-z ]/g,' ').split(/\s+/).filter(x=>x.length>1);return t[t.length-1]??'';};
// Current rule words vs the widened wealth-vehicle set.
const NOW=/\bfamily\s+(office|investment|holdings?)\b/i;
const WIDE=/\bfamily\s+(offices?|investments?|holdings?|capital|wealth|partners|trust|trustees|assets|ventures)\b/i;

let gainNow=0, gainWide=0;
const examples:string[]=[];
for (const r of rows) {
  if (r.classified) continue;
  const match=(r.people??[]).some(p=>{
    const s=surnameOf(p); if(!s||s.length<3||NOT_FAMILY.has(s)) return false;
    return r.canonical_name.toLowerCase().replace(/[^a-z ]/g,' ').split(/\s+/).includes(s);
  });
  if(!match) continue;
  if (NOW.test(r.canonical_name)) gainNow++;
  else if (WIDE.test(r.canonical_name)) { gainWide++; if(examples.length<8) examples.push(r.canonical_name); }
}
console.log(`unclassified qualifying records with a PSC surname match:`);
console.log(`  already matched by the CURRENT vehicle words : ${gainNow}`);
console.log(`  newly matched by the WIDER vehicle words     : ${gainWide}`);
examples.forEach(e=>console.log(`     ${e}`));
TS
